/**
 * Delete User-Granted Compliance Grant Implementation
 *
 * Closes the compliance grant PDA and returns rent to the fee payer.
 * Only the original granter can delete the grant.
 *
 * @remarks
 * ## What This Instruction Does
 *
 * `delete_user_granted_compliance_grant` closes the on-chain marker PDA that
 * was created by `create_user_granted_compliance_grant`. Once deleted:
 * - The receiver can no longer use the grant as authorisation for re-encryption
 *   requests targeting the granter's shared ciphertexts.
 * - The rent SOL from the closed PDA is returned to the fee payer.
 * - Any future attempt by the receiver to call
 *   `reencrypt_user_grant_v11` with the corresponding seed
 *   parameters will fail with an "account does not exist" error.
 *
 * ## When to Revoke
 *
 * - The receiver relationship has ended and viewing access should be removed.
 * - The grant was created in error (wrong receiver, wrong nonce, etc.).
 * - Compliance policy requires periodic grant expiry and renewal.
 *
 * ## Identity Proof: Ed25519 / X25519 Birational Equivalence
 *
 * Identical to grant creation, the granter must prove ownership of their
 * registered X25519 MVK by signing with the birational Ed25519 keypair derived
 * from the master viewing key seed. The on-chain program verifies the signature
 * and confirms the signer's Ed25519 public key birationally maps to the stored
 * `x25519_mvk_public_key` in the granter's user account.
 *
 * See `create-user-granted-compliance-grant.ts` for a full explanation of the
 * birational equivalence identity proof mechanism.
 *
 * ## PDA Seed Matching
 *
 * The grant PDA to be closed is identified by the exact same triple used during
 * creation:
 * - `granterX25519` — granter's MVK X25519 public key (32 bytes)
 * - `nonce` — the nonce used when the grant was created
 * - `receiverX25519` — receiver's X25519 public key (32 bytes)
 *
 * If any of these values differ from the original, the PDA derivation will
 * produce a different address and the instruction will fail (the PDA being
 * referenced will not match the expected discriminator or owner).
 *
 * ## Transaction Flow
 *
 * 1. Derive the MVK proving keypair via `masterViewingKeyX25519KeypairDeriver`.
 * 2. Derive the granter's `EncryptedUserAccount` PDA explicitly from the
 *    wallet address (Codama would otherwise use the proving signer's address).
 * 3. Build the `delete_user_granted_compliance_grant` instruction.
 * 4. Add a `SetComputeUnitLimit(1_200_000)` instruction for Ed25519 signature
 *    verification overhead.
 * 5. Partially sign (MVK proving signer auto-signs), then complete with wallet.
 * 6. Fire pre-callback, forward, fire post-callback.
 *
 * @packageDocumentation
 * @module implementation/umbra/services/compliance/delete-user-granted-compliance-grant
 */

import {
  createNoopSigner,
  createKeyPairSignerFromPrivateKeyBytes,
  appendTransactionMessageInstructions,
  partiallySignTransactionMessageWithSigners,
  createTransactionMessage,
  pipe,
  setTransactionMessageFeePayer,
  setTransactionMessageLifetimeUsingBlockhash,
  type Address,
  type Instruction,
} from "@solana/kit";
import { getDeleteUserGrantInstructionAsync } from "@umbra-privacy/umbra-codama";
import type {
  DeleteUserGrantedComplianceGrantFunction,
  GetDeleteUserGrantedComplianceGrantFunctionArgs,
  GetDeleteUserGrantedComplianceGrantFunctionDeps,
  SignableTransaction,
  TransactionCallbacks,
} from "../../interfaces";
import type {
  OptionalData32,
  RcEncryptionNonce,
  TransactionSignature,
  X25519PublicKey,
} from "../../../types";
import { findEncryptedUserAccountPda } from "../../../common/pda/user";
import { getMasterViewingKeyX25519KeypairDeriver } from "../../../crypto/key-derivation";
import { createSetComputeUnitLimitInstruction } from "../../../solana/constants";

/* =============================================================================
 * CONSTANTS
 * ============================================================================= */

/**
 * Default optional data: 32 zero bytes used when the caller does not supply
 * application-specific metadata.
 *
 * @internal
 */
const DEFAULT_OPTIONAL_DATA_BYTES = new Uint8Array(32);

/* =============================================================================
 * FACTORY FUNCTION
 * ============================================================================= */

/**
 * Creates a function for revoking a previously granted compliance grant.
 *
 * @remarks
 * This follows the SDK factory pattern: the factory is called once during
 * client setup to capture dependencies, and the returned function is called
 * at runtime to delete the grant. The factory resolves the MVK keypair
 * generator at construction time; the returned function calls it once per
 * deletion.
 *
 * Dependency resolution order: explicit `deps` override takes precedence,
 * then the corresponding field on `client`.
 *
 * @param args - Required arguments containing the configured Umbra client.
 *   The client provides the wallet signer, blockhash provider, transaction
 *   forwarder, and network configuration.
 * @param deps - Optional dependency overrides. When provided, each override
 *   replaces the corresponding client-level default. Particularly useful for
 *   injecting a custom `masterViewingKeyX25519KeypairDeriver` in tests.
 * @returns A `DeleteUserGrantedComplianceGrantFunction` that, when called,
 *   builds, signs, and submits the grant deletion transaction on-chain.
 *
 * @example
 * ```typescript
 * import { getDeleteUserGrantedComplianceGrantFunction } from "@umbra-privacy/sdk";
 * import { address } from "@solana/kit";
 *
 * // Create the deletion function (once, at client setup)
 * const deleteGrant = getDeleteUserGrantedComplianceGrantFunction({ client });
 *
 * // Revoke the auditor's viewing access
 * // Parameters must exactly match those used when the grant was created
 * const signature = await deleteGrant(
 *   address("AuditorWalletAddressHere..."),   // receiver (auditor's wallet)
 *   myX25519PublicKey,                        // granter's MVK X25519 public key
 *   auditorX25519PublicKey,                   // receiver's X25519 public key
 *   42n,                                      // same nonce used at creation
 * );
 * console.log("Grant revoked:", signature);
 * ```
 *
 * @see {@link DeleteUserGrantedComplianceGrantFunction} — the type of the returned function
 * @see {@link GetDeleteUserGrantedComplianceGrantFunctionArgs} — factory argument type
 * @see {@link GetDeleteUserGrantedComplianceGrantFunctionDeps} — injectable dependency type
 * @see {@link getCreateUserGrantedComplianceGrantFunction} — creation counterpart
 * @see {@link getQueryUserComplianceGrantFunction} — check whether a grant exists
 * @public
 */
export function getComplianceGrantRevokerFunction(
  args: GetDeleteUserGrantedComplianceGrantFunctionArgs,
  deps?: GetDeleteUserGrantedComplianceGrantFunctionDeps,
): DeleteUserGrantedComplianceGrantFunction {
  const { client } = args;
  const { signer } = client;

  const getLatestBlockhash = deps?.rpc?.blockhashProvider ?? client.blockhashProvider;
  const transactionForwarder = deps?.rpc?.transactionForwarder ?? client.transactionForwarder;
  const masterViewingKeyX25519KeypairDeriver =
    deps?.keys?.masterViewingKeyX25519KeypairDeriver ??
    getMasterViewingKeyX25519KeypairDeriver({ client });

  /**
   * Deletes (revokes) a user-granted compliance grant on-chain.
   *
   * @remarks
   * ## Two-Signer Pattern
   *
   * This instruction requires two signatures:
   * 1. **Wallet signer** (`feePayer`) — pays transaction fees; proves wallet ownership.
   * 2. **MVK proving signer** (`granter`) — an Ed25519 keypair derived from the
   *    master viewing key seed. This signature proves that the caller controls
   *    the X25519 key asserted as the granter identity.
   *
   * The `partiallySignTransactionMessageWithSigners` call handles the MVK
   * proving signer automatically (it is a `KeyPairSigner`). The wallet signer
   * is applied afterward via `signer.signTransaction`.
   *
   * ## PDA Derivation Override
   *
   * The `granterUserAccount` PDA must be derived from the **wallet address**,
   * not from the MVK proving signer address. This function explicitly computes
   * the PDA using `findEncryptedUserAccountPda(userAddress, programId)`.
   *
   * ## Idempotency
   *
   * If the grant PDA has already been deleted (or was never created), the
   * on-chain instruction will fail because the account at the derived address
   * will not be owned by the Umbra program. The caller should use
   * `getQueryUserComplianceGrantFunction` first to verify the grant exists
   * before attempting deletion if idempotent behaviour is required.
   *
   * @param receiver - The Solana wallet address of the receiver whose grant is
   *   being revoked. Must match the address used when the grant was created.
   * @param granterX25519 - The granter's Master Viewing Key X25519 public key
   *   (32 bytes). Must match the key used when the grant was created.
   * @param receiverX25519 - The receiver's X25519 public key (32 bytes). Must
   *   match the key used when the grant was created.
   * @param nonce - The nonce used when the grant was created. Must match exactly.
   * @param optionalData - An optional 32-byte payload for application-level
   *   metadata or tagging. Defaults to 32 zero bytes if not provided.
   * @param callbacks - Optional lifecycle hooks invoked before and after
   *   transaction submission.
   * @returns The transaction signature of the submitted grant deletion transaction.
   *
   * @example
   * ```typescript
   * const sig = await deleteUserGrantedComplianceGrant(
   *   auditorAddress,
   *   myMvkX25519,
   *   auditorX25519,
   *   42n,
   * );
   * ```
   *
   * @public
   */
  return async function deleteUserGrantedComplianceGrant(
    receiver: Address,
    granterX25519: X25519PublicKey,
    receiverX25519: X25519PublicKey,
    nonce: RcEncryptionNonce,
    optionalData?: OptionalData32,
    callbacks?: TransactionCallbacks,
  ): Promise<TransactionSignature> {
    const userAddress = signer.address;
    const programId = client.networkConfig.programId;

    // ================================================================
    // Step 1: Derive the MVK proving signer from the Ed25519 seed
    // ================================================================

    const keypairResult = await masterViewingKeyX25519KeypairDeriver();
    const mvkProvingSigner = await createKeyPairSignerFromPrivateKeyBytes(
      keypairResult.ed25519Keypair.seed,
    );

    // ================================================================
    // Step 2: Derive granter user account PDA from wallet address
    // Must be explicit — Codama would auto-derive from proving signer address.
    // ================================================================

    const _granterUserAccount = await findEncryptedUserAccountPda(userAddress, programId);

    // ================================================================
    // Step 3: Build the instruction
    // ================================================================

    const noopSigner = createNoopSigner(userAddress);
    const instruction: Instruction = await getDeleteUserGrantInstructionAsync({
      feePayer: noopSigner,
      granterX25519ProvingSigner: mvkProvingSigner,
      nonce: { first: nonce },
      granterX25519: { first: granterX25519 },
      receiverX25519: { first: receiverX25519 },
      optionalData: { first: optionalData ?? DEFAULT_OPTIONAL_DATA_BYTES },
    }, { programAddress: client.networkConfig.programId });

    // ================================================================
    // Step 4: Build, sign, and forward the transaction
    // ================================================================

    const latestBlockhash = await getLatestBlockhash();

    const computeBudgetInstruction = createSetComputeUnitLimitInstruction(1_200_000);

    const transactionMessage = pipe(
      createTransactionMessage({ version: 0 }),
      (m) => setTransactionMessageFeePayer(userAddress, m),
      (m) => setTransactionMessageLifetimeUsingBlockhash(latestBlockhash, m),
      (m) => appendTransactionMessageInstructions([computeBudgetInstruction, instruction], m),
    );

    // mvkProvingSigner (KeyPairSigner) auto-signs here; wallet noop slot stays empty
    const partiallySignedTransaction =
      await partiallySignTransactionMessageWithSigners(transactionMessage);

    const signedTransaction = await signer.signTransaction(
      partiallySignedTransaction as SignableTransaction,
    );

    await callbacks?.pre?.(signedTransaction);
    const signatures = await transactionForwarder.forwardInParallel([signedTransaction]);
    const signature = signatures[0];
    await callbacks?.post?.(signedTransaction, signature);
    return signature;
  };
}
