import type { UserRegistrationFunction } from "../../interfaces";
import type { TransactionSignature } from "../../../types";

/**
 * Creates a function that rotates the user account X25519 public key.
 *
 * @remarks
 * This is a convenience wrapper around a pre-built {@link UserRegistrationFunction}
 * that runs only the confidential (X25519 key) registration step with
 * `anonymous: false`. Use this when the client has been constructed with a new
 * `x25519UserAccountPrivateKey` offset and you need to push the updated public
 * key on-chain.
 *
 * The returned function skips the transaction if the current derived key already
 * matches the one stored on-chain. It re-registers (rotates) if the keys differ.
 *
 * @param register - A pre-built registration function created via
 *   `getUserRegistrationFunction({ client }, deps)`.
 * @returns A zero-argument function that executes the key rotation and returns
 *   an array of confirmed transaction signatures (one entry on rotation, empty
 *   array if the key was already up to date).
 *
 * @example
 * ```typescript
 * import {
 *   getUserRegistrationFunction,
 *   getRotateUserAccountX25519KeyFunction,
 * } from "@umbra-privacy/sdk";
 *
 * const register = getUserRegistrationFunction({ client });
 * const rotateKey = getRotateUserAccountX25519KeyFunction(register);
 * const signatures = await rotateKey();
 * console.log("Rotation signatures:", signatures);
 * ```
 *
 * @public
 */
export function getUserEncryptionKeyRotatorFunction(
  register: UserRegistrationFunction,
): () => Promise<TransactionSignature[]> {
  return () => register({ confidential: true, anonymous: false });
}
