/* =============================================================================
 * CONSTANTS
 * ============================================================================= */

/**
 * AES-GCM encryption domain separator for the self-claimable (ephemeral unlocker) variant.
 *
 * @remarks
 * The first 12 bytes of `keccak256("UmbraPrivacy / CreateSelfClaimableUtxoFromEncryptedBalance")`
 * are appended to the 68-byte AES plaintext at offset 56. This tag distinguishes the recovery
 * blob of self-claimable UTXOs from those of receiver-claimable UTXOs during wallet scanning,
 * even though both share the same on-chain `aesEncryptedData` field layout.
 *
 * @internal
 */
const AES_DOMAIN_SEPARATOR_EPHEMERAL = keccak_256(
  new TextEncoder().encode("UmbraPrivacy / CreateSelfClaimableUtxoFromEncryptedBalance"),
).slice(0, 12);

/**
 * KMAC256 domain label for deriving the `modifiedGenerationIndex` from the master seed.
 *
 * @remarks
 * This is the sole point at which `masterSeed` is consumed. The resulting 16-byte
 * `modifiedGenerationIndex` is then used as a deterministic key for all subsequent pure
 * derivations (`expandModifiedGenerationIndex`, `deriveNullifierFromModifiedGenerationIndex`,
 * `deriveRandomSecretFromModifiedGenerationIndex`, etc.) without further access to `masterSeed`.
 * Scoping the domain string to the function name prevents cross-operation key reuse.
 *
 * @internal
 */
const DOMAIN_MODIFIED_GEN_INDEX =
  "EncryptedBalanceToSelfClaimableUtxoCreatorFunction / modifiedGenerationIndex";

/* =============================================================================
 * TYPE CONVERSION HELPERS WITH ASSERTIONS
 * ============================================================================= */

/**
 * Narrows a `bigint` to the {@link Bn254FieldElement} branded type after runtime validation.
 *
 * @remarks
 * Throws a `TypeError` (via `assertBn254FieldElement`) if `value` is outside the BN254 scalar
 * field range `[0, p)` where `p` is the BN254 prime. Used throughout the file to coerce raw
 * arithmetic results into typed circuit inputs.
 *
 * @param value - A non-negative integer to validate and brand as a BN254 field element.
 * @returns The same value typed as {@link Bn254FieldElement}.
 * @throws {TypeError} If `value >= p` (BN254 prime) or is negative.
 *
 * @internal
 */
function toBn254FieldElement(value: bigint): Bn254FieldElement {
  assertBn254FieldElement(value);
  return value;
}

/**
 * Narrows a `bigint` to the {@link U256} branded type after runtime validation.
 *
 * @remarks
 * Throws a `TypeError` if `value` is outside `[0, 2^256)`. Used when encoding field elements or
 * ciphertexts as 32-byte little-endian byte arrays for Solana instruction data.
 *
 * @param value - A non-negative integer to validate and brand as a U256.
 * @returns The same value typed as {@link U256}.
 * @throws {TypeError} If `value >= 2^256` or is negative.
 *
 * @internal
 */
function toU256(value: bigint): U256 {
  assertU256(value);
  return value;
}

/**
 * Narrows a `bigint` to the {@link Curve25519FieldElement} branded type after runtime validation.
 *
 * @remarks
 * Curve25519 field elements must be in `[0, 2^255 - 19)`. Used when constructing Rescue cipher
 * plaintexts and keys, which operate over the Curve25519 scalar field.
 *
 * @param value - A non-negative integer to validate and brand as a Curve25519 field element.
 * @returns The same value typed as {@link Curve25519FieldElement}.
 * @throws {TypeError} If `value` is outside the Curve25519 field.
 *
 * @internal
 */
function toCurve25519FieldElement(value: bigint): Curve25519FieldElement {
  assertCurve25519FieldElement(value);
  return value;
}

/**
 * Validates that `value` is a valid Base85 limb and then brands it as a {@link Bn254FieldElement}.
 *
 * @remarks
 * Base85 limbs are 85-bit chunks produced by {@link convertU256ToBase85Limbs}. After checking the
 * limb range, the function also asserts that the limb fits in the BN254 field (which it always
 * does given 85 < 254 bits). This double assertion makes the constraint explicit in code.
 *
 * @param value - The limb value to validate.
 * @returns The limb typed as {@link Bn254FieldElement}.
 * @throws {TypeError} If `value` is not a valid Base85 limb.
 *
 * @internal
 */
function limbToBn254(value: bigint): Bn254FieldElement {
  assertBase85Limb(value);
  assertBn254FieldElement(value);
  return value as Bn254FieldElement;
}

/**
 * Type guard that checks whether an unknown value is a fully signed {@link SignedTransaction}.
 *
 * @remarks
 * A signed transaction is defined here as an object with both `messageBytes` and `signatures`
 * properties, where `signatures` is a non-empty object (at least one signer has signed).
 * This guard is used after `client.signer.signTransaction` to ensure the wallet did not return
 * an unsigned or partially signed transaction before it is forwarded to the network.
 *
 * @param value - Any value to check.
 * @returns `true` if `value` is a {@link SignedTransaction} with at least one signature.
 *
 * @internal
 */
function isSignedTransaction(value: unknown): value is SignedTransaction {
  if (typeof value !== "object" || value === null) {
    return false;
  }
  const tx = value as Record<string, unknown>;
  // Check for required transaction properties
  return (
    "messageBytes" in tx &&
    "signatures" in tx &&
    tx.signatures instanceof Object &&
    Object.keys(tx.signatures as object).length > 0
  );
}

