  computationData: Address<TAccountComputationData>;
  computationOffset: ClaimIntoNewSharedBalanceV11InstructionDataArgs["computationOffset"];
  feeVaultOffset: ClaimIntoNewSharedBalanceV11InstructionDataArgs["feeVaultOffset"];
