/**
 * MXE to Shared Balance Conversion Implementation
 *
 * This module provides the factory function for converting token accounts
 * from MXE mode to Shared mode. MXE mode accounts can only be decrypted by
 * the Arcium MPC network, while Shared mode accounts can be decrypted by
 * the user's X25519 key.
 *
 * @remarks
 * ## MXE Mode vs. Shared Mode
 *
 * Umbra encrypted token accounts have two decryption modes:
 *
 * - **MXE mode** (Multi-Party Execution only): The balance ciphertext is
 *   encrypted solely under the Arcium network's X25519 public key. Only
 *   the Arcium MPC network can decrypt it. The user cannot read their own
 *   balance without submitting a query to the MPC network.
 *
 * - **Shared mode**: The balance ciphertext is encrypted under **both** the
 *   Arcium network key and the user's registered X25519 key (via the Rescue
 *   cipher). The user can decrypt the balance client-side at any time without
 *   MPC involvement.
 *
 * Conversion from MXE to Shared is a one-way, per-mint operation triggered by
 * the on-chain instruction `convert_network_balance_to_shared_balance_v11`, which queues an
 * Arcium MPC computation to re-encrypt the balance from the network key to the
 * user's X25519 key.
 *
 * ## Prerequisites for Conversion
 *
 * A token account is eligible for conversion if all three of these conditions
 * hold (checked via status bit inspection):
 *
 * - **Bit 0** (`IS_INITIALISED`): The account has been initialised.
 * - **Bit 3** (`IS_SHARED_MODE`) is **false**: The account is currently in MXE
 *   mode. If this bit is already set, conversion would be a no-op.
 * - **Bit 4** (`IS_ARCIUM_BALANCE_INITIALISED`): An encrypted balance exists
 *   in the account. Without an initialised balance there is nothing to convert.
 *
 * Accounts that fail any of these checks are placed in the `skipped` map with
 * a descriptive reason:
 * - `"non_existent"` — PDA not found on-chain
 * - `"not_initialised"` — Bit 0 is zero
 * - `"already_shared"` — Bit 3 is already set
 * - `"balance_not_initialised"` — Bit 4 is zero
 *
 * ## Batch Processing
 *
 * The function accepts a `readonly Address[]` of mints and processes all of
 * them in a single SDK call:
 * 1. Derives token account PDAs for all mints in parallel.
 * 2. Batch-fetches all account data in a single `accountInfoProvider` call.
 * 3. Filters eligible accounts.
 * 4. Builds and signs conversion transactions for all eligible mints in
 *    parallel (sharing a single blockhash fetch).
 * 5. Forwards all transactions in parallel via `transactionForwarder`.
 * 6. Returns a result object separating converted mints from skipped ones.
 *
 * ## Dual-Instruction MPC Pattern
 *
 * Each conversion transaction is a **handler** that queues an Arcium MPC
 * computation (`convert_network_balance_to_shared_balance_v11`). The MPC callback — handled
 * asynchronously by the Arcium network — updates the `IS_SHARED_MODE` status
 * bit and writes the re-encrypted shared-mode balance back into the token
 * account.
 *
 * The SDK does not wait for the MPC callbacks; it returns after all handler
 * transactions are confirmed on-chain.
 *
 * ## Address Lookup Tables
 *
 * When an ALT entry for `"convert_network_balance_to_shared_balance_v11"` is present in
 * the network config, each conversion transaction is compressed using that
 * table to stay within the 1232-byte Solana transaction size limit.
 *
 * ## Status Bit Reference
 *
 * From the Rust on-chain definition:
 * - Bit 0: `is_initialised`
 * - Bit 1: `is_active_for_confidential_usage`
 * - Bit 2: `is_active_for_anonymous_usage`
 * - Bit 3: `is_shared_mode` (TRUE = Shared, FALSE = MXE)
 * - Bit 4: `is_arcium_balance_initialised`
 *
 * @packageDocumentation
 * @module implementation/umbra/services/conversion/mxe-to-shared
 */

import {
  createNoopSigner,
  appendTransactionMessageInstructions,
  compressTransactionMessageUsingAddressLookupTables,
  partiallySignTransactionMessageWithSigners,
  createTransactionMessage,
  pipe,
  setTransactionMessageFeePayer,
  setTransactionMessageLifetimeUsingBlockhash,
  type Address,
  type Instruction,
  type MaybeEncodedAccount,
} from "@solana/kit";
import { buildAltAddressesRecord, lookupAltEntry } from "../../../solana/alt-utils";
import { extractClusterOffsetFromMxeAccount } from "../../../common/arcium";
import {
  getConvertNetworkBalanceToSharedBalanceV11InstructionAsync,
  decodeEncryptedTokenAccount,
} from "@umbra-privacy/umbra-codama";
import type {
  ConvertToSharedEncryptionFunction as ConvertToSharedEncryptionFunction,
  ConvertToSharedEncryptionResult,
  ConvertToSharedEncryptionSkipReason,
  GetConvertToSharedEncryptionFunctionArgs as GetConvertToSharedEncryptionFunctionArgs,
  GetConvertToSharedEncryptionFunctionDeps as GetConvertToSharedEncryptionFunctionDeps,
  SignableTransaction,
  TransactionCallbacks,
} from "../../interfaces";
import type { OptionalData32, TransactionSignature, SignedTransaction } from "../../../types";
import { findEncryptedTokenAccountPda } from "../../../common/pda/user";
import { findArciumInfrastructurePdas } from "../../../common/pda/arcium";
import { generateRandomU64, generateRandomU128 } from "../../../common/math-utils";
import {
  ConversionError,
  TransactionSigningError,
  TransactionError,
  RpcError,
} from "../../../errors";
import type { MicroLamportsPerAcu } from "../../../types/arcium";

/* =============================================================================
 * STATUS BIT CONSTANTS
 * ============================================================================= */

/**
 * Status bit positions for the `EncryptedTokenAccount.statusBits` field.
 *
 * @remarks
 * From the Rust on-chain definition:
 * - Bit 0: `is_initialised`
 * - Bit 1: `is_active_for_confidential_usage`
 * - Bit 2: `is_active_for_anonymous_usage`
 * - Bit 3: `is_shared_mode` (TRUE = Shared, FALSE = MXE)
 * - Bit 4: `is_arcium_balance_initialised`
 *
 * Only the three bits relevant to conversion eligibility are listed here.
 *
 * @internal
 */
const TOKEN_ACCOUNT_STATUS_BITS = {
  IS_INITIALISED: 0,
  IS_SHARED_MODE: 3,
  IS_ARCIUM_BALANCE_INITIALISED: 4,
} as const;

/**
 * Checks if a specific bit is set in a value.
 *
 * @remarks
 * Accepts both `number` and `bigint` to handle both the codama-decoded
 * `statusBits.first` (which may be either type) and direct numeric constants.
 * Uses `BigInt` arithmetic throughout to avoid 32-bit integer truncation
 * for bit positions beyond 30.
 *
 * @param value - The value to check (can be number or bigint).
 * @param bitPosition - The zero-indexed bit position to check.
 * @returns `true` if the bit at `bitPosition` is set; `false` otherwise.
 *
 * @internal
 */
function isBitSet(value: number | bigint, bitPosition: number): boolean {
  return (BigInt(value) & (1n << BigInt(bitPosition))) !== 0n;
}

/**
 * Default optional data: 32 zero bytes used when the caller does not supply
 * application-specific metadata.
 *
 * @internal
 */
const DEFAULT_OPTIONAL_DATA_BYTES = new Uint8Array(32);

/* =============================================================================
 * FACTORY FUNCTION
 * ============================================================================= */

/**
 * Creates a function for converting MXE mode token accounts to Shared mode.
 *
 * @remarks
 * This factory creates a converter that:
 * 1. Derives token account PDAs for each mint using the user's address
 * 2. Batch fetches all account data using the AccountInfoProvider
 * 3. Filters accounts that are eligible for conversion (initialized, MXE mode, balance initialized)
 * 4. Builds conversion instructions for each eligible account
 * 5. Signs and forwards all transactions in parallel
 * 6. Returns a result object showing which mints were converted and which were skipped
 *
 * The factory resolves all dependency defaults at construction time. Each call
 * to the returned function fetches a fresh blockhash and generates fresh random
 * offsets per eligible mint.
 *
 * Dependency resolution order: explicit `deps` override takes precedence,
 * then the corresponding field on `client`.
 *
 * @param args - Required arguments containing the configured Umbra client.
 *   The client provides the wallet signer, blockhash provider, account info
 *   provider, transaction forwarder, and network configuration.
 * @param deps - Optional dependency overrides. When provided, each override
 *   replaces the corresponding client-level default. Useful for testing with
 *   mock account data or custom forwarding logic.
 * @returns A `ConvertToSharedEncryptionFunction` that, when called, batch-processes
 *   the provided mints and returns a result map.
 *
 * @example
 * ```typescript
 * import { getConvertToSharedEncryptionFunction } from "@umbra-privacy/sdk";
 * import { address } from "@solana/kit";
 *
 * // Simple usage with defaults derived from client
 * const convertToShared = getConvertToSharedEncryptionFunction({ client });
 *
 * // Convert multiple mints
 * const mints = [usdcMint, usdtMint];
 * const result = await convertToShared(mints);
 *
 * // Check converted mints
 * for (const [mint, signature] of result.converted) {
 *     console.log(`Converted ${mint}: ${signature}`);
 * }
 *
 * // Check skipped mints
 * for (const [mint, reason] of result.skipped) {
 *     console.log(`Skipped ${mint}: ${reason}`);
 * }
 * ```
 *
 * @example
 * ```typescript
 * // Usage with custom dependencies
 * const convertToShared = getConvertToSharedEncryptionFunction(
 *     { client },
 *     {
 *         accountInfoProvider: customProvider,
 *         transactionForwarder: customForwarder,
 *     }
 * );
 * ```
 *
 * @example
 * ```typescript
 * // With optional data
 * const result = await convertToShared(mints, { first: myOptionalData });
 * ```
 *
 * @see {@link ConvertToSharedEncryptionFunction} — the type of the returned function
 * @see {@link ConvertToSharedEncryptionResult} — the result shape with `converted` and `skipped` maps
 * @see {@link ConvertToSharedEncryptionSkipReason} — possible skip reason strings
 * @see {@link getRotateMintX25519EncryptionKeyFunction} — subsequent key rotation after conversion
 * @see {@link getQueryEncryptedBalanceFunction} — reads balances in shared mode after conversion
 * @public
 */
export function getNetworkEncryptionToSharedEncryptionConverterFunction(
  args: GetConvertToSharedEncryptionFunctionArgs,
  deps?: GetConvertToSharedEncryptionFunctionDeps,
): ConvertToSharedEncryptionFunction {
  const { client } = args;
  const { signer } = client;

  // ========================================================================
  // SOLANA/RPC DEPENDENCIES
  // ========================================================================

  const accountInfoProvider = deps?.rpc?.accountInfoProvider ?? client.accountInfoProvider;

  const getLatestBlockhash = deps?.rpc?.blockhashProvider ?? client.blockhashProvider;

  const transactionForwarder = deps?.rpc?.transactionForwarder ?? client.transactionForwarder;

  // ========================================================================
  // RETURN THE CONVERTER FUNCTION
  // ========================================================================

  /**
   * Converts MXE-mode encrypted token accounts to Shared mode for the given mints.
   *
   * @remarks
   * The function is idempotent with respect to already-shared accounts: they are
   * silently placed in the `skipped` map with reason `"already_shared"` and no
   * transaction is submitted. This makes it safe to call speculatively without
   * first checking each account's current mode.
   *
   * Pre-callbacks are fired for each signed transaction individually, in order,
   * before any are forwarded. Post-callbacks are fired per-transaction as
   * signatures are returned.
   *
   * @param mints - The list of SPL mint addresses whose encrypted token accounts
   *   should be converted to Shared mode. An empty array returns immediately with
   *   empty maps.
   * @param optionalData - An optional 32-byte payload for application-level
   *   metadata or tagging. Applied uniformly to all conversion transactions.
   *   Defaults to 32 zero bytes if not provided.
   * @param callbacks - Optional lifecycle hooks invoked before and after each
   *   individual conversion transaction.
   * @returns A `ConvertToSharedEncryptionResult` containing:
   *   - `converted`: `Map<Address, TransactionSignature>` — mints that were
   *     successfully converted, keyed by mint address.
   *   - `skipped`: `Map<Address, ConvertToSharedEncryptionSkipReason>` — mints
   *     that were skipped, keyed by mint address, with the reason as value.
   *
   * @example
   * ```typescript
   * const { converted, skipped } = await convertToSharedEncryption([usdcMint, solMint]);
   * console.log("Converted:", [...converted.keys()]);
   * console.log("Skipped:", [...skipped.entries()]);
   * ```
   *
   * @param options - Optional. Pass `{ accountInfoCommitment }` to override the
   *   default `"confirmed"` commitment level for account reads.
   * @public
   */
  return async function convertToSharedEncryption(
    mints: readonly Address[],
    optionalData?: OptionalData32,
    callbacks?: TransactionCallbacks,
    microLamportsPerAcu?: MicroLamportsPerAcu,
    options?: { readonly accountInfoCommitment?: "processed" | "confirmed" | "finalized" },
  ): Promise<ConvertToSharedEncryptionResult> {
    const accountInfoCommitment = options?.accountInfoCommitment ?? "confirmed";
    try {
      const converted = new Map<Address, TransactionSignature>();
      const skipped = new Map<Address, ConvertToSharedEncryptionSkipReason>();

      if (mints.length === 0) {
        return { converted, skipped };
      }

      // ================================================================
      // Step 1: Derive token account PDAs for all mints
      // ================================================================

      const userAddress = signer.address;

      const pdaDerivations = await Promise.all(
        mints.map(async (mint) => ({
          mint,
          pda: await findEncryptedTokenAccountPda(
            userAddress,
            mint,
            client.networkConfig.programId,
          ),
        })),
      );

      // Create list of PDAs to fetch
      const pdas: Address[] = pdaDerivations.map(({ pda }) => pda);

      // ================================================================
      // Step 2: Batch fetch all token accounts
      // ================================================================

      const accountMap = await accountInfoProvider([client.networkConfig.mxeAccountAddress, ...pdas], { commitment: accountInfoCommitment });

      const clusterOffset = extractClusterOffsetFromMxeAccount(
        accountMap.get(client.networkConfig.mxeAccountAddress)!,
      );

      // ================================================================
      // Step 3: Filter eligible mints based on status bits
      // ================================================================

      const eligibleMints: Address[] = [];

      for (const { mint, pda } of pdaDerivations) {
        const maybeAccount: MaybeEncodedAccount<Address> | undefined = accountMap.get(pda);

        // Skip if account doesn't exist

         
        if (maybeAccount === undefined || !maybeAccount.exists || maybeAccount.data === undefined) {
          skipped.set(mint, "non_existent");
          continue;
        }

        // Decode the account data
        const decodedAccount = decodeEncryptedTokenAccount(
          maybeAccount as MaybeEncodedAccount<Address> & {
            exists: true;
          },
        );

        const statusBits = decodedAccount.data.statusBits.first;

        // Check eligibility criteria:
        // - Bit 0 (IS_INITIALISED): Must be true
        // - Bit 3 (IS_SHARED_MODE): Must be false (MXE mode)
        // - Bit 4 (IS_ARCIUM_BALANCE_INITIALISED): Must be true
        const isInitialised = isBitSet(statusBits, TOKEN_ACCOUNT_STATUS_BITS.IS_INITIALISED);
        const isSharedMode = isBitSet(statusBits, TOKEN_ACCOUNT_STATUS_BITS.IS_SHARED_MODE);
        const isArciumBalanceInitialised = isBitSet(
          statusBits,
          TOKEN_ACCOUNT_STATUS_BITS.IS_ARCIUM_BALANCE_INITIALISED,
        );

        // Check each condition and record the reason for skipping
        if (!isInitialised) {
          skipped.set(mint, "not_initialised");
          continue;
        }

        if (isSharedMode) {
          skipped.set(mint, "already_shared");
          continue;
        }

        if (!isArciumBalanceInitialised) {
          skipped.set(mint, "balance_not_initialised");
          continue;
        }

        // All criteria met - eligible for conversion
        eligibleMints.push(mint);
      }

      // Return results if no eligible mints (skipped map already populated)
      if (eligibleMints.length === 0) {
        return { converted, skipped };
      }

      // ================================================================
      // Step 4: Build transactions for each eligible mint
      // ================================================================

      // Fetch latest blockhash once for all transactions
      const latestBlockhash = await getLatestBlockhash();

      // Build all transactions in parallel
      const transactionPromises = eligibleMints.map(async (mint) => {
        // Generate random offsets for this transaction
        const computationOffset = generateRandomU64();
        const mpcCallbackDataOffset = generateRandomU128();

        // Get Arcium account addresses
        const arciumAccounts = await findArciumInfrastructurePdas(
          client.networkConfig.programId,
          client.networkConfig.arciumProgramAddress,
          clusterOffset,
          BigInt(computationOffset),
          "convert_network_balance_to_shared_balance_v11",
        );

        // Build the instruction
        const noopSigner = createNoopSigner(userAddress);
        const instruction: Instruction = await getConvertNetworkBalanceToSharedBalanceV11InstructionAsync({
          // Signers (noop signer for instruction building)
          userAddress: noopSigner,
          feePayer: noopSigner,
          // Arcium accounts
          mxeAccount: arciumAccounts.mxeAccount,
          mempoolAccount: arciumAccounts.mempoolAccount,
          executingPool: arciumAccounts.executingPoolAccount,
          computationAccount: arciumAccounts.computationAccount,
          compDefAccount: arciumAccounts.compDefAccount,
          clusterAccount: arciumAccounts.clusterAccount,
          // Token mint
          mint,
          // Instruction data
          computationOffset: {
            first: computationOffset,
          },
          mpcCallbackDataOffset: {
            first: mpcCallbackDataOffset,
          },
          priorityFees: { first: microLamportsPerAcu ?? 0n },
          optionalData: { first: optionalData ?? DEFAULT_OPTIONAL_DATA_BYTES },
        }, { programAddress: client.networkConfig.programId });

        // Build transaction message
        const baseTransactionMessage = pipe(
          createTransactionMessage({ version: 0 }),
          (m) => setTransactionMessageFeePayer(userAddress, m),
          (m) => setTransactionMessageLifetimeUsingBlockhash(latestBlockhash, m),
          (m) => appendTransactionMessageInstructions([instruction], m),
        );

        // Compress with Address Lookup Table (if available)
        const altEntry = lookupAltEntry(client.networkConfig.addressLookupTables, clusterOffset, "convert_network_balance_to_shared_balance_v11");

        const transactionMessage =
          altEntry === undefined
            ? baseTransactionMessage
            : compressTransactionMessageUsingAddressLookupTables(
                baseTransactionMessage,
                buildAltAddressesRecord(altEntry),
              );

        // Compile and partially sign (NoopSigners contribute nothing, leaves wallet slot null)
        const partiallySignedTransaction =
          await partiallySignTransactionMessageWithSigners(transactionMessage);

        // Sign transaction with wallet signer
        const signedTransaction = await signer.signTransaction(
          partiallySignedTransaction as SignableTransaction,
        );

        return { mint, signedTransaction };
      });

      // Wait for all transactions to be built and signed
      const signedTransactions = await Promise.all(transactionPromises);

      // ================================================================
      // Step 5: Forward all transactions in parallel
      // ================================================================

      // Extract signed transactions for forwarding
      const transactionsToForward: SignedTransaction[] = signedTransactions.map(
        ({ signedTransaction }) => signedTransaction,
      );

      // Fire pre callbacks for each transaction before forwarding
      for (const { signedTransaction } of signedTransactions) {
        await callbacks?.pre?.(signedTransaction);
      }

      // Forward all transactions in parallel
      const signatures = await transactionForwarder.forwardInParallel(transactionsToForward);

      // ================================================================
      // Step 6: Build results
      // ================================================================

      for (const [index, signedTransaction] of signedTransactions.entries()) {
        const { mint } = signedTransaction;
        const signature = signatures[index];

         
        if (signature !== undefined) {
          converted.set(mint, signature);
          await callbacks?.post?.(signedTransaction.signedTransaction, signature);
        }
      }

      return { converted, skipped };
    } catch (error: unknown) {
      if (error instanceof ConversionError) {throw error;}
      if (error instanceof TransactionSigningError)
        {throw new ConversionError("transaction-sign", error.message, error);}
      if (error instanceof TransactionError)
        {throw new ConversionError("transaction-send", error.message, error);}
      if (error instanceof RpcError)
        {throw new ConversionError("account-fetch", error.message, error);}
      throw new ConversionError(
        "transaction-send",
        error instanceof Error ? error.message : String(error),
        error instanceof Error ? error : undefined,
      );
    }
  };
}
