/**
 * Reencrypt Shared Ciphertexts (User Grant) Implementation
 *
 * Queues an Arcium MPC computation that re-encrypts shared ciphertexts from
 * the granter's X25519 key to the receiver's X25519 key, using a user-granted
 * compliance grant as authorisation. Fire-and-forget: the SDK sends the handler
 * transaction and returns; the callback is handled asynchronously by Arcium.
 *
 * @remarks
 * ## User-Granted vs. Network-Granted Re-Encryption
 *
 * Both user-granted and network-granted re-encryption operate on shared-mode
 * ciphertexts (encrypted under the granter's X25519 key), but they differ in
 * the source of authority:
 *
 * - **User-granted** (this module): The data subject personally created the
 *   compliance grant PDA via `create_user_granted_compliance_grant`. The
 *   receiver exercises this grant by calling
 *   `reencrypt_user_grant_v11`.
 * - **Network-granted** (`reencrypt-shared-ciphertexts-network-grant.ts`):
 *   The protocol operator or governance issued the grant on the granter's
 *   behalf. The receiver calls `reencrypt_network_grant_for_shared_balance_v11`.
 *
 * ## Threat Model
 *
 * - **Confidentiality**: Re-encryption is performed entirely inside the Arcium
 *   MPC enclave across threshold parties. No single MPC node sees the balance
 *   plaintext.
 * - **Authorization**: The on-chain handler verifies the user-granted compliance
 *   grant PDA (seeded by `granterX25519`, `nonce`, `receiverX25519`) before
 *   enqueuing the computation. A receiver without a valid grant cannot trigger
 *   the MPC computation.
 * - **Integrity**: The `granterX25519Key` and `receiverX25519Key` parameters
 *   are bound into the instruction data; a malicious relayer cannot redirect
 *   output to a different X25519 key without changing the on-chain inputs and
 *   failing the grant PDA check.
 * - **Fund safety**: Re-encryption never moves on-chain funds. The granter's
 *   encrypted token account balance remains unchanged. The operation only
 *   produces re-encrypted output in the Arcium MPC callback data PDA.
 * - **Revocability**: The granter can delete the grant at any time via
 *   `delete_user_granted_compliance_grant`, which closes the PDA and prevents
 *   any further re-encryption under that grant.
 *
 * ## Dual-Instruction MPC Pattern (Fire-and-Forget)
 *
 * This function submits only the **handler** transaction:
 * 1. The handler validates the user-granted compliance grant PDA, pads the
 *    ciphertext array to exactly 6 slots, and queues the Arcium MPC computation.
 * 2. The MPC callback is handled asynchronously by the Arcium network. The
 *    callback stores re-encrypted output ciphertexts in the MPC callback data
 *    PDA so the receiver can retrieve them out-of-band.
 *
 * The function returns the handler transaction signature without waiting for
 * the Arcium MPC callback to complete.
 *
 * ## Ciphertext Padding
 *
 * The on-chain instruction has exactly 6 ciphertext slots
 * (`inputCiphertext0`–`inputCiphertext5`). Unused slots are filled with 32
 * zero bytes (`ZERO_CIPHERTEXT`). The MPC computation reads the actual count
 * from the instruction data and skips padding slots.
 *
 * ## Address Lookup Tables
 *
 * When an ALT entry for `"reencrypt_user_grant_v11"` is
 * present in the network config, the transaction is compressed using that table
 * to stay within the 1232-byte Solana transaction size limit.
 *
 * @packageDocumentation
 * @module implementation/umbra/services/compliance/reencrypt-shared-ciphertexts-user-grant
 */

import {
  createNoopSigner,
  appendTransactionMessageInstructions,
  compressTransactionMessageUsingAddressLookupTables,
  partiallySignTransactionMessageWithSigners,
  createTransactionMessage,
  pipe,
  setTransactionMessageFeePayer,
  setTransactionMessageLifetimeUsingBlockhash,
  type Instruction,
} from "@solana/kit";
import { getReencryptUserGrantV11InstructionAsync } from "@umbra-privacy/umbra-codama";
import type {
  ReencryptSharedCiphertextsUserGrantV10Function,
  GetReencryptSharedCiphertextsUserGrantV10FunctionArgs,
  GetReencryptSharedCiphertextsUserGrantV10FunctionDeps,
  SignableTransaction,
  TransactionCallbacks,
} from "../../interfaces";
import type {
  OptionalData32,
  RcEncryptionNonce,
  TransactionSignature,
  X25519PublicKey,
} from "../../../types";
import { buildAltAddressesRecord, lookupAltEntry } from "../../../solana/alt-utils";
import { extractClusterOffsetFromMxeAccount } from "../../../common/arcium";
import { findArciumInfrastructurePdas } from "../../../common/pda/arcium";
import { generateRandomU64, generateRandomU128 } from "../../../common/math-utils";
import type { MicroLamportsPerAcu } from "../../../types/arcium";

/* =============================================================================
 * CONSTANTS
 * ============================================================================= */

/**
 * The Arcium on-chain instruction name used to derive the computation definition
 * PDA and look up the Address Lookup Table entry.
 *
 * @internal
 */
const INSTRUCTION_NAME = "reencrypt_user_grant_v11";

/**
 * Zero-value placeholder ciphertext for unused slots in the padded ciphertext array.
 * All 32 bytes are zero.
 *
 * @internal
 */
const ZERO_CIPHERTEXT: { first: Uint8Array } = { first: new Uint8Array(32) };

/**
 * Default optional data: 32 zero bytes used when the caller does not supply
 * application-specific metadata.
 *
 * @internal
 */
const DEFAULT_OPTIONAL_DATA_BYTES = new Uint8Array(32);

/**
 * Maximum number of ciphertexts that can be re-encrypted in a single call.
 * The on-chain instruction has exactly 6 fixed ciphertext slots.
 *
 * @internal
 */
const MAX_CIPHERTEXTS = 6;

/* =============================================================================
 * FACTORY FUNCTION
 * ============================================================================= */

/**
 * Creates a function for re-encrypting shared ciphertexts under a user compliance grant.
 *
 * @remarks
 * This follows the SDK factory pattern: the factory is called once during
 * client setup to capture dependencies, and the returned function is called
 * at runtime to queue the MPC computation. Arcium account addresses are
 * derived fresh on each call using a randomly generated `computationOffset`.
 *
 * The calling wallet must be the holder of a valid user-granted compliance
 * grant from the granter (seeded by `granterX25519`, `nonce`, and
 * `receiverX25519`). The on-chain handler verifies this grant PDA before
 * queuing the computation.
 *
 * Dependency resolution order: explicit `deps` override takes precedence,
 * then the corresponding field on `client`.
 *
 * @param args - Required arguments containing the configured Umbra client.
 *   The client provides the wallet signer, blockhash provider, transaction
 *   forwarder, and network configuration including ALT entries.
 * @param deps - Optional dependency overrides. When provided, each override
 *   replaces the corresponding client-level default.
 * @returns A fire-and-forget `ReencryptSharedCiphertextsUserGrantV10Function` that
 *   submits the handler transaction and returns the signature without waiting
 *   for the Arcium MPC callback.
 *
 * @example
 * ```typescript
 * import { getReencryptSharedCiphertextsUserGrantV10Function } from "@umbra-privacy/sdk";
 *
 * // Create the re-encryption function (once, at client setup)
 * // Note: the calling client must be the receiver (the one holding the grant)
 * const reencrypt = getReencryptSharedCiphertextsUserGrantV10Function({ client });
 *
 * // Re-encrypt shared-mode ciphertexts from granter to self (receiver)
 * const signature = await reencrypt(
 *   granterX25519Key,        // 32-byte X25519 key of the data subject (granter)
 *   myX25519Key,             // 32-byte X25519 key of the receiver (this client)
 *   42n,                     // nonce — must match the nonce in the user-granted grant
 *   inputNonce,              // nonce under which the input ciphertexts were encrypted
 *   [ciphertext0, ciphertext1], // array of 32-byte shared-mode ciphertexts (1–6)
 * );
 * console.log("MPC computation queued:", signature);
 * // Poll or subscribe to the MPC callback data PDA to retrieve re-encrypted output
 * ```
 *
 * @example
 * ```typescript
 * // With optional data and lifecycle callbacks
 * const signature = await reencrypt(
 *   granterX25519Key,
 *   myX25519Key,
 *   grantNonce,
 *   inputNonce,
 *   ciphertexts,
 *   new Uint8Array(32),  // optionalData
 *   {
 *     pre: async () => console.log("Submitting re-encryption handler..."),
 *     post: async ({ signature }) => console.log("Handler confirmed:", signature),
 *   },
 * );
 * ```
 *
 * @see {@link ReencryptSharedCiphertextsUserGrantV10Function} — the type of the returned function
 * @see {@link GetReencryptSharedCiphertextsUserGrantV10FunctionArgs} — factory argument type
 * @see {@link getQueryUserComplianceGrantFunction} — check for grant before calling
 * @see {@link getCreateUserGrantedComplianceGrantFunction} — granter creates the grant
 * @see {@link getDeleteUserGrantedComplianceGrantFunction} — granter revokes the grant
 * @see {@link getReencryptNetworkGrantForSharedBalanceV11Function} — network-granted variant
 * @public
 */
export function getSharedCiphertextReencryptorForUserGrantFunction(
  args: GetReencryptSharedCiphertextsUserGrantV10FunctionArgs,
  deps?: GetReencryptSharedCiphertextsUserGrantV10FunctionDeps,
): ReencryptSharedCiphertextsUserGrantV10Function {
  const { client } = args;
  const { signer } = client;

  const accountInfoProvider = client.accountInfoProvider;
  const getLatestBlockhash = deps?.getLatestBlockhash ?? client.blockhashProvider;
  const transactionForwarder = deps?.transactionForwarder ?? client.transactionForwarder;

  /**
   * Queues an Arcium MPC computation to re-encrypt shared-mode ciphertexts from
   * the granter's X25519 key to the receiver's X25519 key, authorised by a
   * user-granted compliance grant.
   *
   * @remarks
   * Unused ciphertext slots (indices `ciphertexts.length` through 5) are filled
   * with 32 zero bytes. Random offsets (`computationOffset` and
   * `mpcCallbackDataOffset`) are generated per call to ensure unique PDA
   * addresses and prevent replay.
   *
   * @param granterX25519Key - The X25519 public key (32 bytes) of the data
   *   subject (granter) who issued the compliance grant. Must match the
   *   `granterX25519` seed component of the grant PDA.
   * @param receiverX25519Key - The X25519 public key (32 bytes) of the party
   *   receiving the re-encrypted output (typically the calling wallet's X25519
   *   key). Must match the `receiverX25519` seed component of the grant PDA.
   * @param nonce - The nonce embedded in the user-granted compliance grant PDA
   *   seed. Must match the nonce used when the grant was created.
   * @param inputEncryptionNonce - The nonce under which the input ciphertexts
   *   were originally encrypted by the granter's X25519 key. Required for the
   *   MPC nodes to correctly decrypt the inputs before re-encrypting.
   * @param ciphertexts - An array of 1–6 shared-mode ciphertexts (each 32
   *   bytes). Must contain at least 1 and no more than `MAX_CIPHERTEXTS` (6).
   * @param optionalData - An optional 32-byte payload for application-level
   *   metadata or tagging. Defaults to 32 zero bytes if not provided.
   * @param callbacks - Optional lifecycle hooks invoked before and after the
   *   handler transaction submission.
   * @returns The transaction signature of the submitted handler transaction.
   * @throws `Error` if `ciphertexts.length` is 0 or greater than 6.
   *
   * @example
   * ```typescript
   * const sig = await reencryptSharedCiphertextsUserGrant(
   *   granterX25519Key, myX25519Key, grantNonce, inputNonce, [ct0],
   * );
   * ```
   *
   * @param options - Optional. Pass `{ accountInfoCommitment }` to override the
   *   default `"confirmed"` commitment level for account reads.
   * @public
   */
  return async function reencryptSharedCiphertextsUserGrant(
    granterX25519Key: X25519PublicKey,
    receiverX25519Key: X25519PublicKey,
    nonce: RcEncryptionNonce,
    inputEncryptionNonce: RcEncryptionNonce,
    ciphertexts: readonly Uint8Array[],
    optionalData?: OptionalData32,
    callbacks?: TransactionCallbacks,
    microLamportsPerAcu?: MicroLamportsPerAcu,
    options?: { readonly accountInfoCommitment?: "processed" | "confirmed" | "finalized" },
  ): Promise<TransactionSignature> {
    const accountInfoCommitment = options?.accountInfoCommitment ?? "confirmed";
    if (ciphertexts.length === 0 || ciphertexts.length > MAX_CIPHERTEXTS) {
      throw new Error(
        `ciphertexts must have 1–${String(MAX_CIPHERTEXTS)} elements, got ${String(ciphertexts.length)}`,
      );
    }

    const userAddress = signer.address;

    // Pad ciphertexts to exactly 6 slots
    const padded = Array.from({ length: MAX_CIPHERTEXTS }, (_, index) =>
      index < ciphertexts.length ? { first: ciphertexts[index] } : ZERO_CIPHERTEXT,
    );

    // ================================================================
    // Step 1: Fetch MXE account and extract cluster offset
    // ================================================================

    const accountMap = await accountInfoProvider([client.networkConfig.mxeAccountAddress], { commitment: accountInfoCommitment });
    const clusterOffset = extractClusterOffsetFromMxeAccount(
      accountMap.get(client.networkConfig.mxeAccountAddress)!,
    );

    // ================================================================
    // Step 2: Generate offsets and derive Arcium accounts
    // ================================================================

    const computationOffset = generateRandomU64();
    const mpcCallbackDataOffset = generateRandomU128();

    const arciumAccounts = await findArciumInfrastructurePdas(
      client.networkConfig.programId,
      client.networkConfig.arciumProgramAddress,
      clusterOffset,
      BigInt(computationOffset),
      INSTRUCTION_NAME,
    );

    // ================================================================
    // Step 3: Build the instruction
    // ================================================================

    const noopSigner = createNoopSigner(userAddress);
    const instruction: Instruction = await getReencryptUserGrantV11InstructionAsync(
      {
        receiver: noopSigner,
        feePayer: noopSigner,
        mxeAccount: arciumAccounts.mxeAccount,
        mempoolAccount: arciumAccounts.mempoolAccount,
        executingPool: arciumAccounts.executingPoolAccount,
        computationAccount: arciumAccounts.computationAccount,
        compDefAccount: arciumAccounts.compDefAccount,
        clusterAccount: arciumAccounts.clusterAccount,
        computationOffset: { first: computationOffset },
        granterX25519Key: { first: granterX25519Key },
        receiverX25519Key: { first: receiverX25519Key },
        nonce: { first: nonce },
        inputEncryptionNonce: { first: inputEncryptionNonce },
        inputCiphertext0: padded[0],
        inputCiphertext1: padded[1],
        inputCiphertext2: padded[2],
        inputCiphertext3: padded[3],
        inputCiphertext4: padded[4],
        inputCiphertext5: padded[5],
        mpcCallbackDataOffset: { first: mpcCallbackDataOffset },
        priorityFees: { first: microLamportsPerAcu ?? 0n },
        optionalData: { first: optionalData ?? DEFAULT_OPTIONAL_DATA_BYTES },
      },
      { programAddress: client.networkConfig.programId },
    );

    // ================================================================
    // Step 4: Build, sign, and forward the transaction
    // ================================================================

    const latestBlockhash = await getLatestBlockhash();

    const baseTransactionMessage = pipe(
      createTransactionMessage({ version: 0 }),
      (m) => setTransactionMessageFeePayer(userAddress, m),
      (m) => setTransactionMessageLifetimeUsingBlockhash(latestBlockhash, m),
      (m) => appendTransactionMessageInstructions([instruction], m),
    );

    const altEntry = lookupAltEntry(client.networkConfig.addressLookupTables, clusterOffset, INSTRUCTION_NAME);

    const transactionMessage =
      altEntry === undefined
        ? baseTransactionMessage
        : compressTransactionMessageUsingAddressLookupTables(
            baseTransactionMessage,
            buildAltAddressesRecord(altEntry),
          );

    const partiallySignedTransaction =
      await partiallySignTransactionMessageWithSigners(transactionMessage);

    const signedTransaction = await signer.signTransaction(
      partiallySignedTransaction as SignableTransaction,
    );

    await callbacks?.pre?.(signedTransaction);
    const signatures = await transactionForwarder.forwardInParallel([signedTransaction]);
    const signature = signatures[0];
    await callbacks?.post?.(signedTransaction, signature);
    return signature;
  };
}
