/* =============================================================================
 * STATUS BIT CONSTANTS
 * ============================================================================= */

/**
 * Status bit flag: bit 2 of the `statusBits.first` field.
 *
 * @remarks
 * This bit is set on the `EncryptedUserAccount` PDA once the user's
 * Poseidon user commitment has been successfully registered via the
 * `register_user_for_anonymous_usage_v11` instruction. When this bit is set,
 * anonymous mode operations (mixer deposits and withdrawals) are available.
 *
 * Used during registration to skip the anonymous commitment step if already done.
 *
 * @see STATUS_BIT_USER_ACCOUNT_X25519_PUBKEY_REGISTERED
 * @internal
 */
const STATUS_BIT_USER_COMMITMENT_REGISTERED = 1n << 2n;

/**
 * Status bit flag: bit 3 of the `statusBits.first` field.
 *
 * @remarks
 * This bit is set on the `EncryptedUserAccount` PDA once the user's
 * X25519 public key has been successfully registered via the
 * `register_token_public_key` instruction. When this bit is set,
 * confidential token operations (encrypted deposits, transfers, withdrawals)
 * are available.
 *
 * Used during registration to skip the X25519 key registration step if already done.
 *
 * @see STATUS_BIT_USER_COMMITMENT_REGISTERED
 * @internal
 */
const STATUS_BIT_USER_ACCOUNT_X25519_PUBKEY_REGISTERED = 1n << 4n;

/* =============================================================================
 * CREATE USER REGISTRATION FUNCTION
 * ============================================================================= */

/**
 * Required arguments for creating a user registration function.
 *
 * @remarks
 * The `client` is the only required argument. It provides the signer, RPC
 * infrastructure, key derivation parameters, and network configuration that
 * the registration function needs to operate.
 *
 * @public
 */
export interface GetUserRegisrationFunctionArgs {
  /**
   * The Umbra client instance.
   *
   * @remarks
   * Must be a fully constructed `IUmbraClient` obtained from
   * {@link getUmbraClient}. The client supplies the `signer` for
   * transaction signing, the `accountInfoProvider` for reading on-chain state,
   * and the `transactionForwarder` for broadcasting transactions.
   */
  readonly client: IUmbraClient;
}

/**
 * Optional dependency overrides for {@link getUserRegistrationFunction}.
 *
 * @remarks
 * Every field defaults to a value derived from the client's pre-constructed
 * dependencies. Override individual fields to inject mocks for testing, swap
 * in custom cryptographic implementations, or provide a non-default ZK prover.
 *
 * The dependency groups reflect the internal structure of the registration flow:
 * - **Solana/RPC** — account reads and transaction submission
 * - **Key derivation** — deterministic key generators from the master seed
 * - **Rescue cipher** — Rescue encryption key generation and ciphertext creation
 * - **Commitment** — Poseidon hash-based user commitment generation
 * - **Challenge/polynomial** — Fiat-Shamir challenge and polynomial evaluation
 * - **Poseidon** — Aggregated public input hash generation
 * - **BN254 arithmetic** — Field arithmetic for non-zero validations
 * - **ZK prover** — Groth16 proof generation for anonymous mode
 *
 * @public
 */
export interface GetUserRegistrationFunctionDeps {
  readonly rpc?: {
    readonly accountInfoProvider?: AccountInfoProviderFunction;
    readonly blockhashProvider?: GetLatestBlockhash;
    readonly transactionForwarder?: TransactionForwarder;
  };

  readonly keys?: {
    readonly userAccountX25519KeypairDeriver?: Curve25519KeypairGeneratorFunction;
    readonly masterViewingKeyEncryptingX25519KeypairDeriver?: Curve25519KeypairGeneratorFunction;
    readonly mintX25519KeypairDeriver?: MintX25519KeypairDeriverFunction;
    readonly masterViewingKeyGenerator?: MasterViewingKeyDeriverFunction;
    readonly masterViewingKeyBlindingFactorGenerator?: MasterViewingKeyBlindingFactorDeriverFunction;
    readonly poseidonPrivateKeyGenerator?: PoseidonPrivateKeyDeriverFunction;
    readonly poseidonBlindingFactorGenerator?: PoseidonBlindingFactorDeriverFunction;
  };

  readonly crypto?: {
    readonly rescueCommitmentBlindingFactorGenerator?: RescueCommitmentBlindingFactorDeriverFunction;
    readonly randomFactorGenerator?: PolynomialCommitmentFactorDeriverFunction;
    readonly getRcKeyGenerator?: (privateKey: X25519PrivateKey) => RcKeyGeneratorFunction;
    readonly getRcEncryptor?: (privateKey: X25519PrivateKey) => RcEncryptorWithNonceFunction;
    readonly rescueCommitmentGenerator?: RescueCommitmentGeneratorFunction;
    readonly userCommitmentGenerator?: UserCommitmentGeneratorFunction;
    readonly fiatShamirChallengeGenerator?: FiatShamirChallengeGeneratorFunction;
    readonly challengePowersFunction?: ChallengePowersFunction;
    readonly polynomialEvaluator?: PolynomialEvaluatorFunction;
    readonly poseidonAggregator?: PoseidonAggregatorHashFunction;
    readonly bn254ModInverter?: ModuleInvFunction;
    readonly computeLimbwiseSumInverse?: (limbs: Base85LimbTuple) => Bn254FieldElement;
  };

  readonly zkProver?: IZkProverForUserRegistration;
}

/**
 * Creates a user registration function bound to the given client and providers.
 *
 * @remarks
 * This factory creates an idempotent registration function that handles the
 * complete three-step Umbra user registration flow. The returned function can
 * be called repeatedly without side effects — it reads on-chain state before
 * each step and skips steps that are already complete.
 *
 * **Registration Steps:**
 *
 * 1. **Account Initialization** (if `EncryptedUserAccount` PDA does not exist)
 *    - Generates a 32-byte random seed for PDA generation
 *    - Calls `initialise_arcium_encrypted_user_account` on-chain
 *    - Creates the PDA that stores the user's registration state and keys
 *
 * 2. **X25519 Key Registration** (if `confidential: true` and bit 3 not set)
 *    - Derives the user account X25519 keypair from the master seed
 *    - Calls `register_token_public_key` on-chain
 *    - Stores the X25519 public key on-chain for ECDH decryption of incoming UTXOs
 *    - Requires 1,200,000 compute units (Ed25519 signature verification)
 *
 * 3. **User Commitment Registration** (if `anonymous: true` and bit 2 not set)
 *    - Derives all required keys (MVK, Poseidon key, blinding factors, etc.)
 *    - Encrypts the MVK and random polynomial factor using the Rescue cipher
 *    - Generates a Fiat-Shamir transcript and computes the ZK public inputs
 *    - Generates a Groth16 ZK proof via the injected `zkProver`
 *    - Calls `register_user_for_anonymous_usage_v11` on-chain
 *    - Requires 1,200,000 compute units (Groth16 verification)
 *
 * **Idempotency:**
 * Status bits are read from the on-chain account before each step. If a step is
 * already complete, the step is skipped silently — no callbacks are invoked
 * and no transaction is submitted.
 *
 * **Prerequisites:**
 * - `anonymous: true` can be used independently of `confidential`
 * - `anonymous: true` requires a `zkProver` in `deps`
 *
 * @param args - Required configuration; the `client` provides all shared state
 * @param deps - Optional dependency overrides for individual components
 * @returns A {@link UserRegistrationFunction} that performs the multi-step
 *   registration flow when called and returns the on-chain transaction signatures
 *
 * @throws {Error} If `anonymous: true` is requested without `confidential: true`
 * @throws {Error} If `anonymous: true` is requested without a `zkProver` in `deps`
 * @throws {Error} If fetching on-chain account info fails (PDA not derivable)
 * @throws {Error} If any on-chain transaction fails to confirm
 *
 * @example
 * ```typescript
 * import { getUserRegistrationFunction } from '@umbra-privacy/sdk';
 *
 * const register = getUserRegistrationFunction({ client });
 *
 * // Register with both confidential and anonymous modes
 * const signatures = await register({ confidential: true, anonymous: true });
 * console.log(`Completed ${signatures.length} registration transactions`);
 * ```
 *
 * @example
 * ```typescript
 * // Registration with UI progress callbacks
 * const register = getUserRegistrationFunction({ client });
 *
 * const signatures = await register({
 *   confidential: true,
 *   anonymous: true,
 *   callbacks: {
 *     userAccountInitialisation: {
 *       pre: (ctx) => {
 *         if (ctx.skipped) setStatus('Account already exists, skipping...');
 *         else setStatus('Creating Umbra account...');
 *       },
 *       post: (ctx) => {
 *         if (!ctx.skipped) setStatus(`Account created: ${ctx.signature}`);
 *       },
 *     },
 *     registerX25519PublicKey: {
 *       pre: (ctx) => {
 *         if (!ctx.skipped) setStatus('Registering encryption key...');
 *       },
 *     },
 *     registerUserForAnonymousUsage: {
 *       pre: (ctx) => {
 *         if (!ctx.skipped) setStatus('Generating ZK proof (this may take a moment)...');
 *       },
 *     },
 *   },
 * });
 * ```
 *
 * @example
 * ```typescript
 * // Confidential mode only (no anonymous / mixer access)
 * const register = getUserRegistrationFunction({ client });
 * const signatures = await register({ confidential: true, anonymous: false });
 * ```
 *
 * @example
 * ```typescript
 * // Full dependency injection for testing
 * const register = getUserRegistrationFunction(
 *   { client: mockClient },
 *   {
 *     rpc: {
 *       accountInfoProvider: mockAccountInfoProvider,
 *       blockhashProvider: async () => ({ blockhash: 'abc', lastValidBlockHeight: 999 }),
 *       transactionForwarder: mockForwarder,
 *     },
 *     zkProver: mockZkProver,
 *   }
 * );
 * ```
 *
 * @see {@link getUmbraClient}
 * @see {@link UserRegistrationFunction}
 * @see {@link UserRegistrationOptions}
 * @public
 */
export function getUserRegistrationFunction(
  args: GetUserRegisrationFunctionArgs,
  deps?: GetUserRegistrationFunctionDeps,
): UserRegistrationFunction {
  const { client } = args;
  const { signer } = client;

  // ========================================================================
  // SOLANA/RPC DEPENDENCIES
  // ========================================================================

  const accountInfoProvider = deps?.rpc?.accountInfoProvider ?? client.accountInfoProvider;

  const getLatestBlockhash = deps?.rpc?.blockhashProvider ?? client.blockhashProvider;

  const transactionForwarder = deps?.rpc?.transactionForwarder ?? client.transactionForwarder;

  // ========================================================================
  // KEY DERIVATION DEPENDENCIES
  // ========================================================================

  const userAccountX25519KeypairDeriver =
    deps?.keys?.userAccountX25519KeypairDeriver ?? getUserAccountX25519KeypairDeriver({ client });

  const masterViewingKeyEncryptingX25519KeypairDeriver =
    deps?.keys?.masterViewingKeyEncryptingX25519KeypairDeriver ??
    getMasterViewingKeyX25519KeypairDeriver({ client });

  const masterViewingKeyGenerator =
    deps?.keys?.masterViewingKeyGenerator ?? getMasterViewingKeyDeriver({ client });

  const masterViewingKeyBlindingFactorGenerator =
    deps?.keys?.masterViewingKeyBlindingFactorGenerator ??
    getMasterViewingKeyBlindingFactorDeriver({ client });

  const poseidonPrivateKeyGenerator =
    deps?.keys?.poseidonPrivateKeyGenerator ?? getPoseidonPrivateKeyDeriver({ client });

  const poseidonBlindingFactorGenerator =
    deps?.keys?.poseidonBlindingFactorGenerator ?? getPoseidonBlindingFactorDeriver({ client });

  const rescueCommitmentBlindingFactorGenerator =
    deps?.crypto?.rescueCommitmentBlindingFactorGenerator ??
    getRescueCommitmentBlindingFactorDeriver({
      client,
    });

  const randomFactorGenerator =
    deps?.crypto?.randomFactorGenerator ?? getPolynomialCommitmentFactorDeriver({ client });

  // ========================================================================
  // RESCUE CIPHER DEPENDENCIES
  // ========================================================================

  const getRcKeyGenerator =
    deps?.crypto?.getRcKeyGenerator ??
    ((pk: Parameters<typeof getRescueKeyGeneratorFromPrivateKey>[0]) =>
      getRescueKeyGeneratorFromPrivateKey(pk, {
        umbraX25519PublicKey: client.networkConfig.mxePubkey,
      }));

  const getRcEncryptor =
    deps?.crypto?.getRcEncryptor ??
    ((pk: Parameters<typeof getRescueEncryptorWithNonceFromPrivateKey>[0]) =>
      getRescueEncryptorWithNonceFromPrivateKey(pk, {
        umbraX25519PublicKey: client.networkConfig.mxePubkey,
      }));

  const rescueCommitmentGenerator =
    deps?.crypto?.rescueCommitmentGenerator ?? getRescueCommitmentGenerator();

  // ========================================================================
  // COMMITMENT DEPENDENCIES
  // ========================================================================

  const userCommitmentGenerator =
    deps?.crypto?.userCommitmentGenerator ?? getUserCommitmentGeneratorFunction();

  // ========================================================================
  // CHALLENGE/POLYNOMIAL DEPENDENCIES
  // ========================================================================

  const fiatShamirChallengeGenerator =
    deps?.crypto?.fiatShamirChallengeGenerator ?? getFiatShamirChallengeGeneratorFunction();

  const challengePowersFunction = deps?.crypto?.challengePowersFunction ?? getChallengePowersFunction();

  const polynomialEvaluator = deps?.crypto?.polynomialEvaluator ?? getPolynomialEvaluatorFunction();

  // ========================================================================
  // POSEIDON DEPENDENCIES
  // ========================================================================

  const poseidonAggregator = deps?.crypto?.poseidonAggregator ?? getPoseidonAggregator();

  // ========================================================================
  // BN254 ARITHMETIC DEPENDENCIES
  // ========================================================================

  const bn254ModuleInverter = deps?.crypto?.bn254ModInverter ?? getBn254ModuleInverter();

  const computeLimbwiseSumInverse =
    deps?.crypto?.computeLimbwiseSumInverse ?? computeBn254LimbwiseSumInverse;

  // ========================================================================
  // ZK PROVER
  // ========================================================================

  const zkProver = deps?.zkProver;

  // ========================================================================
  // Shared Transaction Executor
  // ========================================================================

  const executorConfig: TransactionExecutorConfig = {
    signer,
    getLatestBlockhash,
    transactionForwarder,
    computationMonitor: client.computationMonitor,
  };

  /**
   * Builds, signs, and sends a transaction, invoking lifecycle callbacks around it.
   *
   * @param instruction - The main instruction to execute
   * @param callbacks - Optional pre/post lifecycle callbacks for UI integration
   * @param prefixInstructions - Optional instructions to prepend (e.g. compute budget)
   * @param altEntry - Optional ALT entry for transaction compression
   * @returns The confirmed transaction signature
   *
   * @throws {Error} If building, signing, or sending fails
   *
   * @internal
   */
  async function executeTransactionWithCallbacks(
    instruction: Instruction,
    callbacks: TransactionCallbacks | undefined,
    prefixInstructions?: Instruction[],
    altEntry?: AltEntry,
    awaitCallback?: AwaitCallbackOptions,
  ): Promise<TransactionSignature> {
    const result = await executeComputationTransaction(
      executorConfig,
      {
        instruction,
        preInstructions: prefixInstructions,
        altEntry,
        callbacks,
      },
      awaitCallback,
    );
    return result.signature;
  }

  // ========================================================================
  // Return the registration function
  // ========================================================================

  /**
   * The user registration function that performs up to three sequential on-chain steps.
   *
   * @param options - Registration options controlling which steps are executed
   * @param options.confidential - Enable X25519 key registration for confidential tokens (`true` by default)
   * @param options.anonymous - Enable user commitment registration for mixer access (`true` by default)
   * @param options.callbacks - Optional lifecycle callbacks for each step
   * @param options.optionalData - Optional 32-byte blobs attached to each transaction for indexer use
   * @returns An ordered array of confirmed transaction signatures, one per executed step.
   *   Steps that were already complete (skipped) do not contribute a signature.
   *
   * @throws {Error} If `anonymous: true` is requested without a `zkProver` in `deps`
   * @throws {Error} If any on-chain step fails
   */
  return async (options?: UserRegistrationOptions): Promise<TransactionSignature[]> => {
    const accountInfoCommitment = options?.accountInfoCommitment ?? "confirmed";
    try {
      const {
        confidential = true,
        anonymous = true,
        callbacks,
        optionalData,
        microLamportsPerAcu: userMicroLamportsPerAcu,
      } = options ?? {};
      const microLamportsPerAcu = userMicroLamportsPerAcu ?? (0n as MicroLamportsPerAcu);

      // Default optional data: 32 zero bytes
      const defaultOptionalData = new Uint8Array(32);

      // ================================================================
      // Step 0: Validate input flags
      // ================================================================
      if (anonymous && zkProver === undefined) {
        throw new Error(
          "ZK prover is required for anonymous mode registration. " +
            "Provide zkProver in the deps argument.",
        );
      }

      // ================================================================
      // Step 1: Derive PDA and fetch account state
      // ================================================================
      const userAccountPda = await findEncryptedUserAccountPda(
        signer.address,
        client.networkConfig.programId,
      );

      const accountMap = await accountInfoProvider([userAccountPda, client.networkConfig.mxeAccountAddress], { commitment: accountInfoCommitment });
      const maybeAccount = accountMap.get(userAccountPda);

      // Extract cluster offset from MXE account (fetched in the same batch)
      const clusterOffset = extractClusterOffsetFromMxeAccount(
        accountMap.get(client.networkConfig.mxeAccountAddress)!,
      );

      // Check if provider failed completely
      if (maybeAccount === undefined) {
        throw new Error(`Failed to fetch account info for PDA: ${userAccountPda}`);
      }

      // Extract state - check exists and validate before decoding
      let accountExists = maybeAccount.exists;
      let statusBits = 0n;
      let onChainX25519TokenPublicKey: Uint8Array | undefined;
      let onChainX25519MvkPublicKey: Uint8Array | undefined;
      let onChainUserCommitment: bigint | undefined;

      if (accountExists) {
        // Validate account before decoding:
        // 1. Check program owner
        // 2. Check data size
        // 3. Check discriminator
        const existingAccount = maybeAccount as {
          exists: true;
          programAddress: string;
          data: Uint8Array;
        };

        const isOwnedByUmbra = existingAccount.programAddress === client.networkConfig.programId;
        const hasCorrectSize = existingAccount.data.length >= getEncryptedUserAccountSize();
        const hasCorrectDiscriminator =
          hasCorrectSize &&
          existingAccount.data
            .slice(0, 8)
            .every((byte, index) => byte === ENCRYPTED_USER_ACCOUNT_DISCRIMINATOR[index]);

        if (isOwnedByUmbra && hasCorrectSize && hasCorrectDiscriminator) {
          // Safe to decode - account is a valid EncryptedUserAccount
          const decodedAccount = decodeEncryptedUserAccount(maybeAccount);
          // We've validated the account exists and is valid, so we can safely access data
          if (decodedAccount.exists) {
            statusBits = decodedAccount.data.statusBits.first;
            // Extract on-chain public keys and commitment for key-match checks
            onChainX25519TokenPublicKey = new Uint8Array(
              decodedAccount.data.x25519PublicKeyForTokenEncryption.first,
            );
            onChainX25519MvkPublicKey = new Uint8Array(
              decodedAccount.data.x25519PublicKeyForMasterViewingKeyEncryption.first,
            );
            // Convert 32-byte little-endian user commitment bytes to bigint
            const ucBytes = new Uint8Array(decodedAccount.data.userCommitment.first);
            let ucBigInt = 0n;
            for (let index = ucBytes.length - 1; index >= 0; index--) {
              ucBigInt = (ucBigInt << 8n) | BigInt(ucBytes[index] ?? 0);
            }
            onChainUserCommitment = ucBigInt;
          }
        } else {
          // Account exists but is not a valid EncryptedUserAccount
          // Treat as if account doesn't exist for our purposes
          accountExists = false;
        }
      }
      const isX25519Registered =
        accountExists && (statusBits & STATUS_BIT_USER_ACCOUNT_X25519_PUBKEY_REGISTERED) !== 0n;
      const isUserCommitmentRegistered =
        accountExists && (statusBits & STATUS_BIT_USER_COMMITMENT_REGISTERED) !== 0n;

      const signatures: TransactionSignature[] = [];

      // ================================================================
      // Step 2: Create account if it doesn't exist
      // ================================================================
      if (accountExists) {
        // Account already exists — skip
      } else {
        // Generate random 32-byte seed
        const randomSeed = crypto.getRandomValues(new Uint8Array(32));

        const noopSigner = createNoopSigner(signer.address);
        const createAccountInstruction =
          await getInitialiseEncryptedUserAccountInstructionAsync(
            {
              userAddress: signer.address,
              signer: noopSigner,
              feePayer: noopSigner,
              randomGenerationSeed: {
                first: randomSeed,
              },
              optionalData: {
                first: optionalData?.accountInitialisation ?? defaultOptionalData,
              },
            },
            {
              programAddress: client.networkConfig.programId,
            },
          );

        const signature = await executeTransactionWithCallbacks(
          createAccountInstruction,
          callbacks?.userAccountInitialisation,
        );
        signatures.push(signature);
      }

      // ================================================================
      // Step 3: Register X25519 public key (Confidential Mode)
      // ================================================================
      if (confidential) {
        // Derive user account X25519 keypair (Ed25519 + X25519) from master seed
        const keypairResult = await userAccountX25519KeypairDeriver();
        const localX25519PublicKey = keypairResult.x25519Keypair.publicKey;

        // Skip if already registered with the same key; re-register on key rotation
        const tokenPubkey = onChainX25519TokenPublicKey;
        const x25519KeyMatches =
          isX25519Registered &&
          localX25519PublicKey.length === tokenPubkey?.length &&
          localX25519PublicKey.every((byte, index) => byte === tokenPubkey[index]);

        if (x25519KeyMatches) {
          // X25519 already registered with current key — skip
        } else {
          // Not registered or key has changed (rotation) — register
          const userNoopSigner = createNoopSigner(signer.address);
          const registerX25519Instruction = await getRegisterTokenPublicKeyInstructionAsync(
            {
              feePayer: userNoopSigner,
              user: userNoopSigner,
              x25519ProvingSigner: await createKeyPairSignerFromPrivateKeyBytes(
                keypairResult.ed25519Keypair.seed,
              ),
              optionalData: {
                first: optionalData?.registerX25519PublicKey ?? defaultOptionalData,
              },
            },
            {
              programAddress: client.networkConfig.programId,
            },
          );

          const computeBudgetInstruction = createSetComputeUnitLimitInstruction(1_200_000);

          const signature = await executeTransactionWithCallbacks(
            registerX25519Instruction,
            callbacks?.registerX25519PublicKey,
            [computeBudgetInstruction],
          );
          signatures.push(signature);
        }
      }

      // ================================================================
      // Step 4: Register for anonymous usage (Anonymous Mode)
      // ================================================================
      if (anonymous) {
        // ============================================================
        // Step 4.1: Derive X25519 keys
        // ============================================================

        // Get MVK-encrypting X25519 keypair (Ed25519 + X25519)
        const keypairResult = await masterViewingKeyEncryptingX25519KeypairDeriver();
        const x25519PrivateKey: X25519PrivateKey = keypairResult.x25519Keypair.privateKey;
        const x25519PublicKey = keypairResult.x25519Keypair.publicKey as X25519PublicKey;

        // ============================================================
        // Step 4.2: Derive all required keys and values using injected generators
        // ============================================================

        const masterViewingKey = await masterViewingKeyGenerator();
        const poseidonPrivateKey = await poseidonPrivateKeyGenerator();
        const masterViewingKeyBlindingFactor = await masterViewingKeyBlindingFactorGenerator();
        const poseidonPrivateKeyBlindingFactor = await poseidonBlindingFactorGenerator();

        // Check if on-chain MVK X25519 key matches current key
        const mvkPubkey = onChainX25519MvkPublicKey;
        const mvkKeyMatches =
          isUserCommitmentRegistered &&
          x25519PublicKey.length === mvkPubkey?.length &&
          x25519PublicKey.every((byte, index) => byte === mvkPubkey[index]);

        let shouldSkipAnonymous = false;
        if (mvkKeyMatches) {
          // Also verify user commitment matches
          const localUserCommitment = await userCommitmentGenerator(
            masterViewingKey,
            masterViewingKeyBlindingFactor,
            poseidonPrivateKey,
            poseidonPrivateKeyBlindingFactor,
          );
          shouldSkipAnonymous = (localUserCommitment as bigint) === onChainUserCommitment;
        }

        if (shouldSkipAnonymous) {
          // Keys and commitment match — skip
        } else {
          // Not registered or key/commitment has changed (rotation) — register
          const rescueEncryptionCommitmentBlindingFactor =
            await rescueCommitmentBlindingFactorGenerator(0n as U256);
          const randomFactorForPolynomialCommitment = await randomFactorGenerator(0n as U256);

          // ============================================================
          // Step 4.3: Split values into low/high parts
          // ============================================================

          const mvkParts = splitU256IntoTwoU128s(createU256(masterViewingKey, "masterViewingKey"));
          const masterViewingKeyLow = mvkParts.low;
          const masterViewingKeyHigh = mvkParts.high;

          const x25519PubKeyParts = splitX25519PublicKeyIntoTwoU128s(x25519PublicKey);
          const arcisPublicKeyLow = x25519PubKeyParts.low;
          const arcisPublicKeyHigh = x25519PubKeyParts.high;

          const randomFactorParts = splitU256IntoTwoU128s(
            createU256(randomFactorForPolynomialCommitment, "randomFactorForPolynomialCommitment"),
          );
          const randomFactorLow = randomFactorParts.low;
          const randomFactorHigh = randomFactorParts.high;

          // ============================================================
          // Step 4.4: Convert to Base85 limbs
          // ============================================================

          const masterViewingKeyLowLimbs = convertU256ToBase85Limbs(
            createU256(masterViewingKeyLow, "masterViewingKeyLow"),
          );
          const masterViewingKeyHighLimbs = convertU256ToBase85Limbs(
            createU256(masterViewingKeyHigh, "masterViewingKeyHigh"),
          );
          const randomFactorLowLimbs = convertU256ToBase85Limbs(
            createU256(randomFactorLow, "randomFactorLow"),
          );
          const randomFactorHighLimbs = convertU256ToBase85Limbs(
            createU256(randomFactorHigh, "randomFactorHigh"),
          );

          // ============================================================
          // Step 4.5: Generate Rescue encryption nonce and keys
          // ============================================================

          const rescueEncryptionNonce = generateRandomU128() as Nonce;

          // Get Rescue key generator using injected factory
          const rcKeyGenerator = getRcKeyGenerator(x25519PrivateKey);

          // Generate keys for 4 counters: MVK low, MVK high, RF low, RF high
          const rescueKeys = await rcKeyGenerator(
            [0n as RcCounter, 1n as RcCounter, 2n as RcCounter, 3n as RcCounter],
            rescueEncryptionNonce,
          );

          const keyForMvkLow = rescueKeys.get(0n as RcCounter);
          if (keyForMvkLow === undefined) {
            throw new Error("Missing rescue key for counter 0");
          }
          const keyForMvkHigh = rescueKeys.get(1n as RcCounter);
          if (keyForMvkHigh === undefined) {
            throw new Error("Missing rescue key for counter 1");
          }
          const keyForRfLow = rescueKeys.get(2n as RcCounter);
          if (keyForRfLow === undefined) {
            throw new Error("Missing rescue key for counter 2");
          }
          const keyForRfHigh = rescueKeys.get(3n as RcCounter);
          if (keyForRfHigh === undefined) {
            throw new Error("Missing rescue key for counter 3");
          }

          // Convert keys to Base85 limbs
          const keyForMvkLowLimbs = convertU256ToBase85Limbs(
            createU256(keyForMvkLow, "keyForMvkLow"),
          );
          const keyForMvkHighLimbs = convertU256ToBase85Limbs(
            createU256(keyForMvkHigh, "keyForMvkHigh"),
          );
          const keyForRfLowLimbs = convertU256ToBase85Limbs(createU256(keyForRfLow, "keyForRfLow"));
          const keyForRfHighLimbs = convertU256ToBase85Limbs(
            createU256(keyForRfHigh, "keyForRfHigh"),
          );

          // ============================================================
          // Step 4.6: Encrypt values with Rescue cipher
          // ============================================================

          // Get Rescue encryptor using injected factory
          const rcEncryptor = getRcEncryptor(x25519PrivateKey);

          const ciphertexts = await rcEncryptor(
            [
              createRcPlaintext(masterViewingKeyLow, "masterViewingKeyLow"),
              createRcPlaintext(masterViewingKeyHigh, "masterViewingKeyHigh"),
              createRcPlaintext(randomFactorLow, "randomFactorLow"),
              createRcPlaintext(randomFactorHigh, "randomFactorHigh"),
            ],
            rescueEncryptionNonce,
          );

          const encryptedMvkLow = ciphertexts[0];
           
          if (encryptedMvkLow === undefined) {
            throw new Error("Missing ciphertext at index 0");
          }
          const encryptedMvkHigh = ciphertexts[1];
           
          if (encryptedMvkHigh === undefined) {
            throw new Error("Missing ciphertext at index 1");
          }
          const encryptedRfLow = ciphertexts[2];
           
          if (encryptedRfLow === undefined) {
            throw new Error("Missing ciphertext at index 2");
          }
          const encryptedRfHigh = ciphertexts[3];
           
          if (encryptedRfHigh === undefined) {
            throw new Error("Missing ciphertext at index 3");
          }

          // Convert ciphertexts to Base85 limbs
          const encryptedMvkLowLimbs = convertU256ToBase85Limbs(
            createU256(encryptedMvkLow, "encryptedMvkLow"),
          );
          const encryptedMvkHighLimbs = convertU256ToBase85Limbs(
            createU256(encryptedMvkHigh, "encryptedMvkHigh"),
          );
          const encryptedRfLowLimbs = convertU256ToBase85Limbs(
            createU256(encryptedRfLow, "encryptedRfLow"),
          );
          const encryptedRfHighLimbs = convertU256ToBase85Limbs(
            createU256(encryptedRfHigh, "encryptedRfHigh"),
          );

          // ============================================================
          // Step 4.7: Generate Rescue encryption commitment
          // ============================================================

          const rescueEncryptionCommitment = await rescueCommitmentGenerator(
            [encryptedMvkLow, encryptedMvkHigh, encryptedRfLow, encryptedRfHigh],
            [
              createCurve25519FieldElement(masterViewingKeyLow, "masterViewingKeyLow"),
              createCurve25519FieldElement(masterViewingKeyHigh, "masterViewingKeyHigh"),
              createCurve25519FieldElement(randomFactorLow, "randomFactorLow"),
              createCurve25519FieldElement(randomFactorHigh, "randomFactorHigh"),
            ],
            [
              createCurve25519FieldElement(keyForMvkLow, "keyForMvkLow"),
              createCurve25519FieldElement(keyForMvkHigh, "keyForMvkHigh"),
              createCurve25519FieldElement(keyForRfLow, "keyForRfLow"),
              createCurve25519FieldElement(keyForRfHigh, "keyForRfHigh"),
            ],
            rescueEncryptionCommitmentBlindingFactor,
            rescueEncryptionNonce,
            arcisPublicKeyLow,
            arcisPublicKeyHigh,
          );

          // ============================================================
          // Step 4.8: Generate user commitment
          // ============================================================

          const userCommitment = await userCommitmentGenerator(
            masterViewingKey,
            masterViewingKeyBlindingFactor,
            poseidonPrivateKey,
            poseidonPrivateKeyBlindingFactor,
          );

          // ============================================================
          // Step 4.9: Generate Fiat-Shamir challenge and powers
          // ============================================================

          // Build transcript for Fiat-Shamir challenge
          // Format: x25519_pubkey (32) + nonce (16) + 4 ciphertexts (128) + commitment (32) + user_commitment (32) = 240 bytes
          const fiatShamirTranscript = new Uint8Array(240);
          let offset = 0;

          // 1. X25519 public key (32 bytes)
          fiatShamirTranscript.set(x25519PublicKey, offset);
          offset += 32;

          // 2. Nonce as little-endian 16 bytes
          const nonceBytes = new Uint8Array(16);
          let nonceValue = BigInt(rescueEncryptionNonce);
          for (let index = 0; index < 16; index++) {
            nonceBytes[index] = Number(nonceValue & 0xffn);
            nonceValue >>= 8n;
          }
          fiatShamirTranscript.set(nonceBytes, offset);
          offset += 16;

          // 3-6. Four ciphertexts as LE bytes (32 bytes each)
          const ciphertextValues = [
            encryptedMvkLow,
            encryptedMvkHigh,
            encryptedRfLow,
            encryptedRfHigh,
          ];
          for (const ct of ciphertextValues) {
            const ctBytes = encodeU256ToU256LeBytes(createU256(ct, "ciphertext"));
            fiatShamirTranscript.set(ctBytes, offset);
            offset += 32;
          }

          // 7. Rescue encryption commitment (32 bytes LE)
          const commitmentBytes = encodeU256ToU256LeBytes(
            createU256(rescueEncryptionCommitment, "rescueEncryptionCommitment"),
          );
          fiatShamirTranscript.set(commitmentBytes, offset);
          offset += 32;

          // 8. User commitment (32 bytes LE)
          const userCommitmentBytes = encodeU256ToU256LeBytes(
            createU256(userCommitment, "userCommitment"),
          );
          fiatShamirTranscript.set(userCommitmentBytes, offset);

          const fiatShamirChallenge = fiatShamirChallengeGenerator(fiatShamirTranscript);

          // Compute challenge squared
          const challengePowers = challengePowersFunction(fiatShamirChallenge, 2);
          const challengeSquared = challengePowers[2];
           
          if (challengeSquared === undefined) {
            throw new Error("Missing challenge power at index 2");
          }

          // Convert challenge and squared to Base85 limbs
          const challengeLimbs = convertU256ToBase85Limbs(
            createU256(fiatShamirChallenge, "fiatShamirChallenge"),
          );
          const challengeSquaredLimbs = convertU256ToBase85Limbs(
            createU256(challengeSquared, "challengeSquared"),
          );

          // ============================================================
          // Step 4.10: Evaluate polynomial at challenge point
          // ============================================================

          // p(x) = mvkLow + mvkHigh * x + randomFactor * x^2
          const polynomialResult = polynomialEvaluator(
            [
              createCurve25519FieldElement(masterViewingKeyLow, "masterViewingKeyLow"),
              createCurve25519FieldElement(masterViewingKeyHigh, "masterViewingKeyHigh"),
              randomFactorForPolynomialCommitment,
            ],
            fiatShamirChallenge,
          );

          const polynomialResultLimbs = convertU256ToBase85Limbs(
            createU256(polynomialResult, "polynomialResult"),
          );

          // ============================================================
          // Step 4.11: Compute aggregated public input hash
          // ============================================================

          // Build the 26 field elements for aggregation
          const aggregatorInputs: Bn254FieldElement[] = [
            // 1. userCommitment
            userCommitment,
            // 2-3. arcisPublicKey low/high
            createBn254FieldElement(arcisPublicKeyLow, "arcisPublicKeyLow"),
            createBn254FieldElement(arcisPublicKeyHigh, "arcisPublicKeyHigh"),
            // 4. nonce
            createBn254FieldElement(rescueEncryptionNonce, "rescueEncryptionNonce"),
            // 5-7. encrypted MVK low limbs
            createBn254FieldElement(encryptedMvkLowLimbs.low, "encryptedMvkLowLimbs.low"),
            createBn254FieldElement(encryptedMvkLowLimbs.middle, "encryptedMvkLowLimbs.middle"),
            createBn254FieldElement(encryptedMvkLowLimbs.high, "encryptedMvkLowLimbs.high"),
            // 8-10. encrypted MVK high limbs
            createBn254FieldElement(encryptedMvkHighLimbs.low, "encryptedMvkHighLimbs.low"),
            createBn254FieldElement(encryptedMvkHighLimbs.middle, "encryptedMvkHighLimbs.middle"),
            createBn254FieldElement(encryptedMvkHighLimbs.high, "encryptedMvkHighLimbs.high"),
            // 11-13. encrypted RF low limbs
            createBn254FieldElement(encryptedRfLowLimbs.low, "encryptedRfLowLimbs.low"),
            createBn254FieldElement(encryptedRfLowLimbs.middle, "encryptedRfLowLimbs.middle"),
            createBn254FieldElement(encryptedRfLowLimbs.high, "encryptedRfLowLimbs.high"),
            // 14-16. encrypted RF high limbs
            createBn254FieldElement(encryptedRfHighLimbs.low, "encryptedRfHighLimbs.low"),
            createBn254FieldElement(encryptedRfHighLimbs.middle, "encryptedRfHighLimbs.middle"),
            createBn254FieldElement(encryptedRfHighLimbs.high, "encryptedRfHighLimbs.high"),
            // 17. rescueEncryptionCommitment
            rescueEncryptionCommitment,
            // 18-20. challenge limbs
            createBn254FieldElement(challengeLimbs.low, "challengeLimbs.low"),
            createBn254FieldElement(challengeLimbs.middle, "challengeLimbs.middle"),
            createBn254FieldElement(challengeLimbs.high, "challengeLimbs.high"),
            // 21-23. challenge squared limbs
            createBn254FieldElement(challengeSquaredLimbs.low, "challengeSquaredLimbs.low"),
            createBn254FieldElement(challengeSquaredLimbs.middle, "challengeSquaredLimbs.middle"),
            createBn254FieldElement(challengeSquaredLimbs.high, "challengeSquaredLimbs.high"),
            // 24-26. polynomial evaluation result limbs
            createBn254FieldElement(polynomialResultLimbs.low, "polynomialResultLimbs.low"),
            createBn254FieldElement(polynomialResultLimbs.middle, "polynomialResultLimbs.middle"),
            createBn254FieldElement(polynomialResultLimbs.high, "polynomialResultLimbs.high"),
          ];

          const aggregatedPublicInput = await poseidonAggregator(aggregatorInputs);

          // ============================================================
          // Step 4.12: Compute all inverse values for non-zero validation
          // ============================================================

          // Native BN254 field element inverses (6 inverses)
          // Note: All branded field elements are bigints, so we pass them directly
          // The mod inverter returns a bigint which we assert as Bn254FieldElement
          const inverseForPrivateKey = createBn254FieldElement(
            bn254ModuleInverter(poseidonPrivateKey),
            "inverseForPrivateKey",
          );
          const inverseForMasterViewingKeyNative = createBn254FieldElement(
            bn254ModuleInverter(masterViewingKey),
            "inverseForMasterViewingKeyNative",
          );
          const inverseForBlindingFactorRescueCommitment = createBn254FieldElement(
            bn254ModuleInverter(rescueEncryptionCommitmentBlindingFactor),
            "inverseForBlindingFactorRescueCommitment",
          );
          const inverseForMasterViewingKeyBlindingFactor = createBn254FieldElement(
            bn254ModuleInverter(masterViewingKeyBlindingFactor),
            "inverseForMasterViewingKeyBlindingFactor",
          );
          const inverseForPrivateKeyBlindingFactor = createBn254FieldElement(
            bn254ModuleInverter(poseidonPrivateKeyBlindingFactor),
            "inverseForPrivateKeyBlindingFactor",
          );
          const inverseForNonce = createBn254FieldElement(
            bn254ModuleInverter(BigInt(rescueEncryptionNonce)),
            "inverseForNonce",
          );

          // Limbwise inverses (10 inverses)
          const inverseForMasterViewingKeyLow = computeLimbwiseSumInverse(masterViewingKeyLowLimbs);
          const inverseForMasterViewingKeyHigh =
            computeLimbwiseSumInverse(masterViewingKeyHighLimbs);
          const inverseForRandomFactorLowLimbs = computeLimbwiseSumInverse(randomFactorLowLimbs);
          const inverseForRandomFactorHighLimbs = computeLimbwiseSumInverse(randomFactorHighLimbs);
          const inverseForKeysMasterViewingKeyLow = computeLimbwiseSumInverse(keyForMvkLowLimbs);
          const inverseForKeysMasterViewingKeyHigh = computeLimbwiseSumInverse(keyForMvkHighLimbs);
          const inverseForKeysRandomFactorLowLimbs = computeLimbwiseSumInverse(keyForRfLowLimbs);
          const inverseForKeysRandomFactorHighLimbs = computeLimbwiseSumInverse(keyForRfHighLimbs);
          const inverseForChallengeLimbs = computeLimbwiseSumInverse(challengeLimbs);
          const inverseForChallengeSquaredLimbs = computeLimbwiseSumInverse(challengeSquaredLimbs);

          // ============================================================
          // Step 4.13: Build ZK circuit inputs
          // ============================================================

          // Helper to convert Base85LimbTuple (interface) to ZK tuple format
          const toZkLimbTuple = (limbs: Base85LimbTuple): ZkBase85LimbTuple => [
            limbs.low,
            limbs.middle,
            limbs.high,
          ];

          const zkCircuitInputs: UserRegistrationCircuitInputs = {
            // Native BN254 Elements (10 signals)
            privateKey: poseidonPrivateKey,
            masterViewingKey,
            masterViewingKeyLow: createBn254FieldElement(
              masterViewingKeyLow,
              "zkCircuitInputs.masterViewingKeyLow",
            ),
            masterViewingKeyHigh: createBn254FieldElement(
              masterViewingKeyHigh,
              "zkCircuitInputs.masterViewingKeyHigh",
            ),
            blindingFactorForRescueCommitment: rescueEncryptionCommitmentBlindingFactor,
            masterViewingKeyBlindingFactor,
            privateKeyBlindingFactor: poseidonPrivateKeyBlindingFactor,
            arcisPublicKeyLow: createBn254FieldElement(
              arcisPublicKeyLow,
              "zkCircuitInputs.arcisPublicKeyLow",
            ),
            arcisPublicKeyHigh: createBn254FieldElement(
              arcisPublicKeyHigh,
              "zkCircuitInputs.arcisPublicKeyHigh",
            ),
            nonce: createBn254FieldElement(rescueEncryptionNonce, "zkCircuitInputs.nonce"),

            // Limbwise Elements (10 arrays × 3 limbs = 30 signals)
            masterViewingKeyLowLimbs: toZkLimbTuple(masterViewingKeyLowLimbs),
            masterViewingKeyHighLimbs: toZkLimbTuple(masterViewingKeyHighLimbs),
            randomFactorForPolynomialEvaluationLowLimbs: toZkLimbTuple(randomFactorLowLimbs),
            randomFactorForPolynomialEvaluationHighLimbs: toZkLimbTuple(randomFactorHighLimbs),
            keysForMasterViewingKeyLowLimbs: toZkLimbTuple(keyForMvkLowLimbs),
            keysForMasterViewingKeyHighLimbs: toZkLimbTuple(keyForMvkHighLimbs),
            keysForRandomFactorLowLimbs: toZkLimbTuple(keyForRfLowLimbs),
            keysForRandomFactorHighLimbs: toZkLimbTuple(keyForRfHighLimbs),
            challengeLimbs: toZkLimbTuple(challengeLimbs),
            challengeSquaredLimbs: toZkLimbTuple(challengeSquaredLimbs),

            // Inverse Inputs (16 signals)
            inverseForPrivateKey,
            inverseForMasterViewingKeyNative,
            inverseForMasterViewingKeyLow,
            inverseForMasterViewingKeyHigh,
            inverseForBlindingFactorRescueCommitment,
            inverseForMasterViewingKeyBlindingFactor,
            inverseForPrivateKeyBlindingFactor,
            inverseForRandomFactorLowLimbs,
            inverseForRandomFactorHighLimbs,
            inverseForKeysMasterViewingKeyLow,
            inverseForKeysMasterViewingKeyHigh,
            inverseForKeysRandomFactorLowLimbs,
            inverseForKeysRandomFactorHighLimbs,
            inverseForChallengeLimbs,
            inverseForChallengeSquaredLimbs,
            inverseForNonce,

            // Public Input (1 signal)
            publicAggregatedHash: aggregatedPublicInput,
          };

          // ============================================================
          // Step 4.14: Generate ZK proof
          // ============================================================

          if (zkProver === undefined) {
            throw new Error("zkProver is required for anonymous registration");
          }
          const zkProof = await zkProver.prove(zkCircuitInputs);

          // ============================================================
          // Step 4.15: Generate computation offset and Arcium addresses
          // ============================================================

          const computationOffset = generateRandomU64();

          const arciumAccounts = await findArciumInfrastructurePdas(
            client.networkConfig.programId,
            client.networkConfig.arciumProgramAddress,
            clusterOffset,
            BigInt(computationOffset),
            "register_user_for_anonymous_usage_v11",
          );

          // ============================================================
          // Step 4.16: Build instruction
          // ============================================================

          const userNoopSigner = createNoopSigner(signer.address);
          const registerAnonymousInstruction =
            await getRegisterUserForAnonymousUsageV11InstructionAsync(
              {
                user: userNoopSigner,
                feePayer: userNoopSigner,
                mxeAccount: arciumAccounts.mxeAccount,
                mempoolAccount: arciumAccounts.mempoolAccount,
                executingPool: arciumAccounts.executingPoolAccount,
                computationAccount: arciumAccounts.computationAccount,
                compDefAccount: arciumAccounts.compDefAccount,
                clusterAccount: arciumAccounts.clusterAccount,
                computationOffset: {
                  first: computationOffset,
                },
                rescueEncryptionNonce: {
                  first: rescueEncryptionNonce,
                },
                rescueEncryptedMasterViewingKeyLow: {
                  first: encodeU256ToU256LeBytes(createU256(encryptedMvkLow, "encryptedMvkLow")),
                },
                rescueEncryptedMasterViewingKeyHigh: {
                  first: encodeU256ToU256LeBytes(createU256(encryptedMvkHigh, "encryptedMvkHigh")),
                },
                rescueEncryptedRandomFactorForPolynomialLow: {
                  first: encodeU256ToU256LeBytes(createU256(encryptedRfLow, "encryptedRfLow")),
                },
                rescueEncryptedRandomFactorForPolynomialHigh: {
                  first: encodeU256ToU256LeBytes(createU256(encryptedRfHigh, "encryptedRfHigh")),
                },
                rescueEncryptionCommitment: {
                  first: encodeU256ToU256LeBytes(
                    createU256(rescueEncryptionCommitment, "rescueEncryptionCommitment"),
                  ),
                },
                rescueEncryptionPolynomialValidator: {
                  first: encodeU256ToU256LeBytes(createU256(polynomialResult, "polynomialResult")),
                },
                userCommitment: {
                  first: encodeU256ToU256LeBytes(createU256(userCommitment, "userCommitment")),
                },
                groth16ProofA: {
                  first: zkProof.proofA,
                },
                groth16ProofB: {
                  first: zkProof.proofB,
                },
                groth16ProofC: {
                  first: zkProof.proofC,
                },
                x25519ProvingSigner: await createKeyPairSignerFromPrivateKeyBytes(
                  keypairResult.ed25519Keypair.seed,
                ),
                priorityFees: { first: microLamportsPerAcu },
                optionalData: {
                  first: optionalData?.registerUserForAnonymousUsage ?? defaultOptionalData,
                },
              },
              {
                programAddress: client.networkConfig.programId,
              },
            );

          // ============================================================
          // Step 4.17: Execute transaction with compute budget
          // ============================================================

          // ZK proof verification requires increased compute units
          const computeBudgetInstruction = createSetComputeUnitLimitInstruction(1_200_000);

          const registrationAltEntry =
            lookupAltEntry(client.networkConfig.addressLookupTables, clusterOffset, "register_user_for_anonymous_usage_v11");

          const signature = await executeTransactionWithCallbacks(
            registerAnonymousInstruction,
            callbacks?.registerUserForAnonymousUsage,
            [computeBudgetInstruction],
            registrationAltEntry,
            {
              retrieveCallbackSignature: true,
              computationAccountAddress: arciumAccounts.computationAccount,
              computationOffset: BigInt(computationOffset),
              clusterOffset,
            },
          );
          signatures.push(signature);
        }
      }

      // ================================================================
      // Return all signatures
      // ================================================================
      return signatures;
    } catch (error: unknown) {
      if (error instanceof RegistrationError) { throw error; }
      if (error instanceof MasterSeedSigningRejectedError) {
        throw new RegistrationError("master-seed-derivation", error.message, error);
      }
      if (error instanceof TransactionSigningError) {
        throw new RegistrationError("transaction-sign", error.message, error);
      }
      if (error instanceof CryptographyError) {
        throw new RegistrationError("zk-proof-generation", error.message, error);
      }
      if (error instanceof TransactionError) {
        throw new RegistrationError("transaction-send", error.message, error);
      }
      if (error instanceof RpcError) {
        throw new RegistrationError("account-fetch", error.message, error);
      }
      throw new RegistrationError(
        "transaction-send",
        error instanceof Error ? error.message : String(error),
        error instanceof Error ? error : undefined,
      );
    }
  };
}
