/* =============================================================================
 * STATUS BIT CONSTANTS
 * ============================================================================= */

// ============================================================================
// User Account Status Bits
// ============================================================================

/**
 * Bit position in the User Account's `statusBits.first` field that signals
 * whether the user has registered an X25519 public key.
 *
 * @remarks
 * When this bit is set (1), the user has completed X25519 key registration in
 * their `EncryptedUserAccount`, enabling Shared mode for new Encrypted
 * Token Accounts. Shared mode allows the user to decrypt their own balance
 * locally using their X25519 private key, in addition to the standard Arcium
 * MPC decryption path.
 *
 * When this bit is unset (0), only MXE-mode token accounts can be created or
 * deposited into, and the `NewMxeBalance` or `ExistingMxeBalance` instruction
 * variants are selected accordingly.
 *
 * The value `3` means the bit mask is `1 << 3 = 8`.
 *
 * @see {@link isBitSet} - Helper that reads this bit
 * @see {@link TOKEN_STATUS_BIT_SHARED_MODE} - Analogous bit on the token account
 * @internal
 */
const USER_STATUS_BIT_X25519_REGISTERED = 4;

// ============================================================================
// Token Account Status Bits
// ============================================================================

/**
 * Bit position in the Encrypted Token Account's `statusBits.first` field that
 * signals whether the account uses Shared mode encryption.
 *
 * @remarks
 * - **Bit set (1)**: The encrypted balance is in Shared mode. Both the Arcium
 *   MPC network and the user (via their registered X25519 key) can decrypt it.
 *   The `ExistingSharedBalance` instruction variant must be used for deposits.
 * - **Bit unset (0)**: The encrypted balance is in MXE mode. Only the Arcium
 *   MPC network can decrypt it. The `ExistingMxeBalance` instruction variant
 *   must be used for deposits.
 *
 * The value `3` means the bit mask is `1 << 3 = 8`.
 *
 * @see {@link TOKEN_STATUS_BIT_BALANCE_INITIALISED} - Companion bit for balance init state
 * @internal
 */
const TOKEN_STATUS_BIT_SHARED_MODE = 3;

/**
 * Bit position in the Encrypted Token Account's `statusBits.first` field that
 * signals whether the encrypted balance has been initialized (i.e., a first
 * deposit has already occurred).
 *
 * @remarks
 * - **Bit set (1)**: The balance has been initialized. The "Existing" instruction
 *   variants (`ExistingMxeBalance`, `ExistingSharedBalance`) must be used to
 *   avoid re-initializing account state.
 * - **Bit unset (0)**: The balance has never been set. This can happen when the
 *   token account PDA exists on-chain (e.g., was created by a previous instruction)
 *   but has not yet received a deposit. The "New" instruction variants
 *   (`NewMxeBalance`, `NewSharedBalance`) should be used.
 *
 * The value `4` means the bit mask is `1 << 4 = 16`.
 *
 * @see {@link TOKEN_STATUS_BIT_SHARED_MODE} - Companion bit for encryption mode
 * @internal
 */
const TOKEN_STATUS_BIT_BALANCE_INITIALISED = 4;

/**
 * Checks whether a specific bit is set in a `bigint` status-bits value.
 *
 * @remarks
 * Status bits in Umbra on-chain accounts are stored as a `u64` packed bitfield,
 * decoded by the Codama-generated client as a JavaScript `bigint`. This helper
 * tests whether bit number `bit` (0-indexed from the least-significant end)
 * is set using a standard bit-mask operation.
 *
 * @param statusBits - The packed status bits value from an on-chain account,
 *   typically `account.data.statusBits.first` (the lower 64 bits)
 * @param bit - Zero-based bit position to test (e.g., `3` tests bit mask `1 << 3 = 8`)
 * @returns `true` if the specified bit is set; `false` otherwise
 *
 * @example
 * ```typescript
 * const hasX25519 = isBitSet(userAccount.data.statusBits.first, USER_STATUS_BIT_X25519_REGISTERED);
 * const isShared  = isBitSet(tokenAccount.data.statusBits.first, TOKEN_STATUS_BIT_SHARED_MODE);
 * ```
 *
 * @internal
 */
function isBitSet(statusBits: bigint, bit: number): boolean {
  return (statusBits & (1n << BigInt(bit))) !== 0n;
}

/* =============================================================================
 * INSTRUCTION VARIANT ENUM
 * ============================================================================= */

/**
 * Discriminated union of the four Arcium instruction variants available for
 * ATA-to-ETA deposits.
 *
 * @remarks
 * Each variant maps to a distinct Codama-generated instruction builder and a
 * distinct computation definition (comp def) on the Arcium network. The correct
 * variant is selected at runtime based on the on-chain state of the destination
 * User Account and Encrypted Token Account:
 *
 * - **`NewMxeBalance`**: The destination's User Account does not yet exist, or
 *   the user has no registered X25519 key and the token account either does not
 *   exist or has not been initialized. Creates both accounts in MXE mode.
 *   Maps to `deposit_from_public_balance_into_new_network_balance_v11`.
 *
 * - **`ExistingMxeBalance`**: The token account already has an initialized MXE
 *   balance. Adds to the existing encrypted balance without re-initialization.
 *   Maps to `deposit_from_public_balance_into_existing_network_balance_v11`.
 *
 * - **`NewSharedBalance`**: The user has a registered X25519 key but the token
 *   account either does not exist or has not been initialized. Creates accounts
 *   in Shared mode (user-decryptable). Does NOT supply `randomGenerationSeed`
 *   (unlike `NewMxeBalance`) because the seed is derived from the X25519 key.
 *   Maps to `deposit_from_public_balance_into_new_shared_balance_v11`.
 *
 * - **`ExistingSharedBalance`**: The token account already has an initialized
 *   Shared-mode balance. Adds to the existing encrypted balance.
 *   Maps to `deposit_from_public_balance_into_existing_shared_balance_v11`.
 *
 * @see {@link getPublicBalanceToEncryptedBalanceDirectDepositorFunction} - Where variant selection occurs
 * @internal
 */
const DepositInstructionVariant = {
  NewMxeBalance: "NewMxeBalance",
  ExistingMxeBalance: "ExistingMxeBalance",
  NewSharedBalance: "NewSharedBalance",
  ExistingSharedBalance: "ExistingSharedBalance",
} as const;

/**
 * Type alias for the values of {@link DepositInstructionVariant}.
 * @internal
 */
type DepositInstructionVariant =
  (typeof DepositInstructionVariant)[keyof typeof DepositInstructionVariant];

/* =============================================================================
 * FACTORY FUNCTION
 * ============================================================================= */

/**
 * Creates an ATA-to-ETA deposit function bound to the given Umbra client.
 *
 * @remarks
 * This factory implements the "direct deposit" path in Umbra: tokens move from
 * the user's public Associated Token Account (ATA) directly into their Encrypted
 * Token Account (ETA) without passing through the mixer. The resulting transaction
 * queues an Arcium MPC computation; the MPC network's callback will finalize the
 * encrypted balance update.
 *
 * **Factory Pattern:**
 * Calling `getPublicBalanceToEncryptedBalanceDirectDepositorFunction(args, deps)` immediately
 * validates dependencies and captures them in a closure. The returned function
 * (`depositIntoEncryptedBalance`) can then be called multiple times without
 * repeating setup work.
 *
 * **Transaction Pipeline (per invocation of the returned function):**
 * 1. Validate and normalize all input parameters.
 * 2. Fetch the mint account to determine the token program (SPL Token vs Token-2022).
 * 3. For Token-2022 mints with a `TransferFeeConfig` extension, compute the net
 *    deposit amount after deducting the transfer fee at the current epoch.
 * 4. Derive the Encrypted User Account PDA and Encrypted Token Account PDA for
 *    the destination address.
 * 5. Fetch both PDAs to read their on-chain state (existence, status bits).
 * 6. Select the appropriate instruction variant based on the decision tree in
 *    {@link DepositInstructionVariant}.
 * 7. Generate a random `computationOffset` (u64) and `mpcCallbackDataOffset` (u128)
 *    to identify this specific MPC computation instance.
 * 8. Derive all required Arcium account PDAs using `findArciumInfrastructurePdas`.
 * 9. Build the Codama-generated instruction with all accounts and data.
 * 10. Assemble, compress (with ALT if available), partially sign, wallet-sign,
 *     and submit the transaction.
 * 11. Return the transaction signature.
 *
 * **Address Lookup Tables (ALTs):**
 * Each instruction variant has its own ALT entry in `client.networkConfig.addressLookupTables`,
 * keyed by the snake_case instruction name (e.g., `deposit_from_public_balance_into_new_network_balance_v11`).
 * The ALT compresses the large number of Arcium accounts, keeping transactions
 * within the Solana size limit.
 *
 * **`randomGenerationSeed`:**
 * Only the `NewMxeBalance` variant includes a `randomGenerationSeed` field —
 * a 32-byte random value used to seed the initial encrypted balance generation
 * on the Arcium network. The Shared-mode variants derive their seed from the
 * X25519 key instead.
 *
 * **Dependency Injection:**
 * The `deps` parameter is intended for test environments. In production, all
 * dependencies default to the client's own providers. Overridable dependencies
 * include `accountInfoProvider`, `getLatestBlockhash`, `transactionForwarder`,
 * and `getEpochInfo`.
 *
 * @param args - Required configuration. Must contain an initialized `IUmbraClient`
 *   with `accountInfoProvider`, `blockhashProvider`, `transactionForwarder`, and
 *   `epochInfoProvider` properties set.
 * @param deps - Optional dependency overrides. All fields default to the
 *   corresponding providers on the client.
 * @returns A {@link PublicBalanceToEncryptedBalanceDirectDepositorFunction} that, when called,
 *   executes the full deposit pipeline and returns the transaction signature.
 *
 * @throws {EncryptedDepositError} During execution of the returned function, with
 *   a discriminated `stage` field indicating at which step the failure occurred:
 *   `"validation"`, `"mint-fetch"`, `"fee-calculation"`, `"pda-derivation"`,
 *   `"account-fetch"`, `"instruction-build"`, `"transaction-build"`,
 *   `"transaction-compile"`, `"transaction-sign"`, or `"transaction-send"`.
 *
 * @example
 * Basic usage with defaults:
 * ```typescript
 * import { getPublicBalanceToEncryptedBalanceDirectDepositorFunction } from '@umbra-privacy/sdk';
 *
 * const deposit = getPublicBalanceToEncryptedBalanceDirectDepositorFunction({ client });
 *
 * // Self-deposit with all defaults (priorityFees=0, optionalData=zeros)
 * const signature = await deposit(
 *   client.signer.address,
 *   usdcMint,
 *   1000n as U64
 * );
 * ```
 *
 * @example
 * With priority fees:
 * ```typescript
 * const signature = await deposit(
 *   recipientAddress,
 *   usdcMint,
 *   500n as U64,
 *   { priorityFees: 10000n as U64 }
 * );
 * ```
 *
 * @example
 * With all options:
 * ```typescript
 * const signature = await deposit(
 *   recipientAddress,
 *   usdcMint,
 *   500n as U64,
 *   {
 *     priorityFees: 10000n as U64,
 *     optionalData: myOptionalData
 *   }
 * );
 * ```
 *
 * @example
 * With custom dependencies:
 * ```typescript
 * const deposit = getPublicBalanceToEncryptedBalanceDirectDepositorFunction(
 *   { client },
 *   {
 *     accountInfoProvider: myCustomProvider,
 *     transactionForwarder: myCustomForwarder,
 *   }
 * );
 * ```
 *
 * @see {@link PublicBalanceToEncryptedBalanceDirectDepositorFunction} - The type of the returned function
 * @see {@link PublicBalanceToEncryptedBalanceDirectDepositorOptions} - Options accepted by the returned function
 * @see {@link DepositInstructionVariant} - The four instruction variants
 *
 * @public
 */
export function getPublicBalanceToEncryptedBalanceDirectDepositorFunction(
  args: GetPublicBalanceToEncryptedBalanceDirectDepositorFunctionArgs,
  deps?: GetPublicBalanceToEncryptedBalanceDirectDepositorFunctionDeps,
): PublicBalanceToEncryptedBalanceDirectDepositorFunction {
  const { client } = args;
  const { signer } = client;

  // ========================================================================
  // SOLANA/RPC DEPENDENCIES
  // ========================================================================

  const accountInfoProvider = deps?.rpc?.accountInfoProvider ?? client.accountInfoProvider;

  const getLatestBlockhash = deps?.rpc?.blockhashProvider ?? client.blockhashProvider;

  const transactionForwarder = deps?.rpc?.transactionForwarder ?? client.transactionForwarder;

  const getEpochInfo = deps?.rpc?.epochInfo ?? client.epochInfoProvider;

  // Factory-level behaviour config
  const factoryMicroLamportsPerAcu = deps?.arcium?.microLamportsPerAcu ?? (0n as MicroLamportsPerAcu);
  const factoryAwaitComputationFinalization = deps?.arcium?.awaitComputationFinalization;

  // ========================================================================
  // HELPER: Execute a single transaction
  // ========================================================================

  /**
   * Assembles, signs, and submits a single Solana transaction containing
   * the given instruction. Optionally applies an Address Lookup Table (ALT)
   * to compress the account list.
   *
   * @remarks
   * The transaction lifecycle is:
   * 1. Fetch the latest blockhash (for transaction lifetime).
   * 2. Construct a versioned (v0) transaction message with the fee payer,
   *    blockhash, and the single instruction.
   * 3. If an `altEntry` is provided, compress the transaction using the ALT
   *    to reduce transaction size (Arcium instructions reference many accounts).
   * 4. Partially sign the compiled transaction — `NoopSigner`s contribute
   *    nothing; they are placeholders for signers that sign externally.
   * 5. Have the wallet signer sign the transaction.
   * 6. Forward (submit and confirm) the signed transaction.
   *
   * Each step wraps errors in an `EncryptedDepositError` with a descriptive
   * `stage` value so callers can distinguish network failures from signing
   * failures from serialization errors.
   *
   * @param instruction - The single Solana instruction to include in the transaction
   * @param altEntry - Optional ALT entry used to compress the account list.
   *   When provided, `compressTransactionMessageUsingAddressLookupTables` is
   *   called to replace inline account pubkeys with ALT index references.
   * @returns The base-58 encoded transaction signature returned by the forwarder
   *
   * @throws {EncryptedDepositError} With stage `"transaction-build"` if blockhash
   *   fetching or transaction message construction fails
   * @throws {EncryptedDepositError} With stage `"transaction-compile"` if partial
   *   signing / compilation fails
   * @throws {EncryptedDepositError} With stage `"transaction-sign"` if the wallet
   *   signer rejects or fails
   * @throws {EncryptedDepositError} With stage `"transaction-send"` if the forwarder
   *   returns no signature or the RPC rejects the transaction
   *
   * @internal
   */
  // Create the shared transaction executor configuration
  const executorConfig: TransactionExecutorConfig = {
    signer,
    getLatestBlockhash,
    transactionForwarder,
    computationMonitor: client.computationMonitor,
  };

  async function executeTransaction(
    instruction: Instruction,
    altEntry?: AltEntry,
    preInstructions?: Instruction[],
    awaitCallback?: AwaitCallbackOptions,
  ): Promise<DepositResult> {
    // Build, sign, forward, and optionally monitor using the shared utility
    try {
      const result = await executeComputationTransaction(
        executorConfig,
        {
          instruction,
          preInstructions: [
            createSetComputeUnitLimitInstruction(1_200_000),
            ...(preInstructions ?? []),
          ],
          altEntry,
        },
        awaitCallback,
      );
      if ("callbackResult" in result) {
        return {
          queueSignature: result.signature,
          callbackStatus: result.callbackResult.status,
          callbackSignature:
            "callbackSignature" in result.callbackResult
              ? result.callbackResult.callbackSignature
              : undefined,
          callbackElapsedMs: result.callbackResult.elapsedMs,
          rentClaimSignature: result.rentClaimSignature,
          rentClaimError: result.rentClaimError,
        };
      }
      return { queueSignature: result.signature };
    } catch (error) {
      if (error instanceof EncryptedDepositError) {
        throw error;
      }
      throw new EncryptedDepositError(
        "transaction-send",
        `Transaction execution failed: ${error instanceof Error ? error.message : String(error)}`,
        error instanceof Error ? error : undefined,
      );
    }
  }

  // ========================================================================
  // RETURN THE DEPOSIT FUNCTION
  // ========================================================================

  /**
   * Executes a direct ATA-to-ETA token deposit for a given destination and mint.
   *
   * @remarks
   * This function performs the full deposit pipeline:
   * 1. Validate all inputs (amounts, addresses).
   * 2. Fetch the mint account and compute the net deposit amount after any
   *    Token-2022 transfer fees.
   * 3. Derive the destination's Encrypted User Account and Encrypted Token
   *    Account PDAs.
   * 4. Read on-chain state to select the correct instruction variant.
   * 5. Generate computation offsets and fetch Arcium account addresses.
   * 6. Build the Codama-generated instruction.
   * 7. Execute and return the transaction signature.
   *
   * **Amount Semantics:**
   * - `transferAmount`: The amount of tokens deducted from the source ATA.
   *   This is what the user specifies.
   * - `depositAmount` (computed internally): The amount credited to the ETA.
   *   For Token-2022 mints with a transfer fee, `depositAmount = transferAmount - fee`.
   *   For SPL Token mints, `depositAmount = transferAmount`.
   * Both values are passed to the on-chain instruction so the program can verify
   * the arithmetic without fetching the mint itself.
   *
   * **Optional Data:**
   * `optionalData` is a 32-byte blob stored in the deposit record for
   * application-layer use as arbitrary metadata.
   *
   * @param destinationAddress - The Solana address whose Encrypted Token Account
   *   will receive the deposit. Can be the signer's own address (self-deposit) or
   *   any other registered Umbra user's address.
   * @param mint - The SPL token or Token-2022 mint address for the token being deposited.
   * @param transferAmount - The number of tokens (in base units, as a u64 bigint)
   *   to transfer from the source ATA. Must be greater than zero.
   * @param options - Optional configuration overrides.
   * @param options.priorityFees - Compute unit price in lamports. Defaults to `0n`.
   * @param options.optionalData - 32-byte application metadata blob. Defaults to
   *   32 zero bytes.
   * @returns A promise that resolves to the base-58 encoded transaction signature
   *   of the confirmed deposit transaction.
   *
   * @throws {EncryptedDepositError} With stage `"validation"` for invalid inputs.
   * @throws {EncryptedDepositError} With stage `"mint-fetch"` if the mint account
   *   cannot be read or belongs to an unknown token program.
   * @throws {EncryptedDepositError} With stage `"fee-calculation"` if the computed
   *   net deposit amount after token-2022 transfer fees is zero or negative.
   * @throws {EncryptedDepositError} With stage `"pda-derivation"` if PDA computation fails.
   * @throws {EncryptedDepositError} With stage `"account-fetch"` if the User Account
   *   or Token Account cannot be fetched or decoded.
   * @throws {EncryptedDepositError} With stage `"instruction-build"` if the
   *   Codama-generated instruction builder fails or an unknown variant is reached.
   * @throws {EncryptedDepositError} From `executeTransaction` for transaction-level
   *   failures (blockhash, compilation, signing, submission).
   */
  return async function depositIntoEncryptedBalance(
    destinationAddress: Address,
    mint: Address,
    transferAmount: U64,
    options?: PublicBalanceToEncryptedBalanceDirectDepositorOptions,
  ): Promise<DepositResult> {
    const accountInfoCommitment = options?.accountInfoCommitment ?? "confirmed";
    const epochInfoCommitment = options?.epochInfoCommitment ?? "confirmed";
    // ================================================================
    // Step 1: Extract options with defaults
    // ================================================================

    const microLamportsPerAcu = factoryMicroLamportsPerAcu;
    const optionalData = options?.optionalData ?? new Uint8Array(32);

    // ================================================================
    // Step 2: Validate input parameters using assertions
    // ================================================================

    try {
      // Validate addresses (must be non-empty strings)
      if (destinationAddress.trim().length === 0) {
        throw new EncryptedDepositError(
          "validation",
          "Invalid destinationAddress: must be a non-empty string",
        );
      }

      if (mint.trim().length === 0) {
        throw new EncryptedDepositError("validation", "Invalid mint: must be a non-empty string");
      }

      // Validate transferAmount using branded type assertion
      assertU64(transferAmount);
      if (transferAmount <= 0n) {
        throw new EncryptedDepositError(
          "validation",
          "Invalid transferAmount: must be greater than zero",
        );
      }

      // Validate optionalData using branded type assertion
      assertOptionalData32(optionalData, "optionalData");
    } catch (error) {
      // Re-throw EncryptedDepositError as-is
      if (error instanceof EncryptedDepositError) {
        throw error;
      }
      // Wrap assertion errors in EncryptedDepositError
      throw new EncryptedDepositError(
        "validation",
        error instanceof Error ? error.message : String(error),
        error instanceof Error ? error : undefined,
      );
    }

    // ================================================================
    // Step 3: Fetch mint account and calculate deposit amount
    // ================================================================

    let depositAmount: U64;
    let mintOwner: Address;

    try {
      // Fetch the mint account to determine if it's legacy SPL Token or Token-2022
      const mintAccountMap = await accountInfoProvider([mint], { commitment: accountInfoCommitment });
      const mintAccount = mintAccountMap.get(mint);

      if (mintAccount?.exists !== true) {
        throw new EncryptedDepositError("mint-fetch", `Mint account not found: ${mint}`);
      }

      mintOwner = mintAccount.programAddress;

      // Check if this is a Token-2022 mint
      if (mintOwner === TOKEN_2022_PROGRAM_ID) {
        // Get raw mint data from the account
        const mintData = new Uint8Array(mintAccount.data);

        // Try to extract Transfer Fee Config extension
        const feeConfig = extractTransferFeeConfig(mintData);

        if (feeConfig === null) {
          // Token-2022 without Transfer Fee extension - no fee deduction
          depositAmount = transferAmount;
        } else {
          // Token-2022 with Transfer Fee extension - get current epoch and calculate fee
          const epochInfo = await getEpochInfo({ commitment: epochInfoCommitment });
          const transferFee = calculateTransferFee(feeConfig, epochInfo.epoch, transferAmount);

          // Deposit amount is transfer amount minus the fee
          const calculatedDepositAmount = transferAmount - transferFee;

          if (calculatedDepositAmount <= 0n) {
            throw new EncryptedDepositError(
              "fee-calculation",
              `Transfer fee (${String(transferFee)}) exceeds or equals transfer amount (${String(transferAmount)}). Deposit amount must be greater than zero.`,
            );
          }

          // Assert the calculated amount is a valid U64
          assertU64(calculatedDepositAmount);
          depositAmount = calculatedDepositAmount;
        }
      } else if (mintOwner === SPL_TOKEN_PROGRAM_ID) {
        // Legacy SPL Token - no transfer fees
        depositAmount = transferAmount;
      } else {
        // Unknown token program
        throw new EncryptedDepositError(
          "mint-fetch",
          `Unknown token program: ${mintOwner}. Expected SPL Token (${SPL_TOKEN_PROGRAM_ID}) or Token-2022 (${TOKEN_2022_PROGRAM_ID})`,
        );
      }
    } catch (error) {
      // Re-throw EncryptedDepositError as-is
      if (error instanceof EncryptedDepositError) {
        throw error;
      }
      throw new EncryptedDepositError(
        "mint-fetch",
        `Failed to fetch mint account: ${error instanceof Error ? error.message : String(error)}`,
        error instanceof Error ? error : undefined,
      );
    }

    // ================================================================
    // Step 4: Derive PDA addresses
    // ================================================================

    let encryptedTokenAccountPda: Address;
    let encryptedUserAccountPda: Address;

    try {
      [encryptedTokenAccountPda, encryptedUserAccountPda] = await Promise.all([
        findEncryptedTokenAccountPda(destinationAddress, mint, client.networkConfig.programId),
        findEncryptedUserAccountPda(destinationAddress, client.networkConfig.programId),
      ]);
    } catch (error) {
      throw new EncryptedDepositError(
        "pda-derivation",
        `Failed to derive PDA addresses: ${error instanceof Error ? error.message : String(error)}`,
        error instanceof Error ? error : undefined,
      );
    }

    // ================================================================
    // Step 5: Fetch user account and token account state
    // ================================================================

    let maybeUserAccount;
    let maybeTokenAccount;
    let clusterOffset: number;

    try {
      // Fetch MXE, user, and token accounts in parallel
      const accountMap = await accountInfoProvider([
        client.networkConfig.mxeAccountAddress,
        encryptedUserAccountPda,
        encryptedTokenAccountPda,
      ], { commitment: accountInfoCommitment });

      const encodedUserAccount = accountMap.get(encryptedUserAccountPda);
      const encodedTokenAccount = accountMap.get(encryptedTokenAccountPda);

      if (encodedUserAccount === undefined) {
        throw new EncryptedDepositError(
          "account-fetch",
          `Failed to fetch account info for user PDA: ${encryptedUserAccountPda}`,
        );
      }

      if (encodedTokenAccount === undefined) {
        throw new EncryptedDepositError(
          "account-fetch",
          `Failed to fetch account info for token PDA: ${encryptedTokenAccountPda}`,
        );
      }

      // Decode accounts
      maybeUserAccount = decodeEncryptedUserAccount(encodedUserAccount);
      maybeTokenAccount = decodeEncryptedTokenAccount(encodedTokenAccount);

      // Extract cluster offset from MXE account (fetched in the same batch)
      clusterOffset = extractClusterOffsetFromMxeAccount(
        accountMap.get(client.networkConfig.mxeAccountAddress)!,
      );
    } catch (error) {
      if (error instanceof EncryptedDepositError) {
        throw error;
      }
      throw new EncryptedDepositError(
        "account-fetch",
        `Failed to fetch accounts: ${error instanceof Error ? error.message : String(error)}`,
        error instanceof Error ? error : undefined,
      );
    }

    // ================================================================
    // Step 6: Determine instruction variant based on account states
    // ================================================================
    //
    // Decision tree:
    //
    // Case 1: User Account Does NOT Exist
    //   └─► NewMxeBalance
    //
    // Case 2: User Account DOES Exist
    //   ├─ Subcase 2.1: NO X25519 key registered
    //   │   ├─ Token exists + balance init + shared mode → ERROR (invalid)
    //   │   ├─ Token exists + balance init + MXE mode → ExistingMxeBalance
    //   │   └─ Token doesn't exist OR balance not init → NewMxeBalance
    //   │
    //   └─ Subcase 2.2: HAS X25519 key registered
    //       ├─ Token exists + balance init + shared mode → ExistingSharedBalance
    //       ├─ Token exists + balance init + MXE mode → ExistingMxeBalance
    //       └─ Token doesn't exist OR balance not init → NewSharedBalance
    //
    // ================================================================

    let instructionVariant: DepositInstructionVariant;

    // Case 1: User Account does NOT exist
    if (maybeUserAccount.exists) {
      // Case 2: User Account EXISTS
      const userStatusBits = maybeUserAccount.data.statusBits.first;
      const hasX25519Key = isBitSet(userStatusBits, USER_STATUS_BIT_X25519_REGISTERED);

      // Check token account state
      const tokenExists = maybeTokenAccount.exists;
      let isSharedMode = false;
      let isBalanceInitialised = false;

      if (tokenExists) {
        const tokenStatusBits = maybeTokenAccount.data.statusBits.first;
        isSharedMode = isBitSet(tokenStatusBits, TOKEN_STATUS_BIT_SHARED_MODE);
        isBalanceInitialised = isBitSet(tokenStatusBits, TOKEN_STATUS_BIT_BALANCE_INITIALISED);
      }

      // ================================================================
      // Step 5.5: Reset stuck ETA queue before depositing
      //
      // If the token account has an initialised balance with >= 4 queued
      // computations that have been pending for >= 180 slots, the queue
      // is considered stuck. We reset it (MXE or Shared variant based on
      // mode), await the MPC callback + rent reclaim, then fall through
      // to the normal deposit path.
      // ================================================================

      if (tokenExists && isBalanceInitialised) {
        const queueCount = maybeTokenAccount.data.queuedComputationCount.first; // number (u8)
        if (queueCount >= 4) {
          const oldestSlot = maybeTokenAccount.data.oldestPendingSlot.first; // bigint
          const epochInfo = await getEpochInfo({ commitment: epochInfoCommitment });
          const currentSlot = epochInfo.absoluteSlot; // bigint
          if (currentSlot - oldestSlot >= 180n) {
            const resetCompDefName = isSharedMode
              ? "reset_shared_eta_queue_v9"
              : "reset_mxe_eta_queue_v9";
            const resetComputationOffset = generateRandomU64();
            const resetMpcCallbackDataOffset = generateRandomU128();
            const resetArciumAccounts = await findArciumInfrastructurePdas(
              client.networkConfig.programId,
              client.networkConfig.arciumProgramAddress,
              clusterOffset,
              BigInt(resetComputationOffset),
              resetCompDefName,
            );
            const resetAltEntry = lookupAltEntry(client.networkConfig.addressLookupTables, clusterOffset, resetCompDefName);
            const resetBaseParams = {
              feePayer: createNoopSigner(signer.address),
              mxeAccount: resetArciumAccounts.mxeAccount,
              mempoolAccount: resetArciumAccounts.mempoolAccount,
              executingPool: resetArciumAccounts.executingPoolAccount,
              computationAccount: resetArciumAccounts.computationAccount,
              compDefAccount: resetArciumAccounts.compDefAccount,
              clusterAccount: resetArciumAccounts.clusterAccount,
              userAddress: destinationAddress,
              userTokenAccount: encryptedTokenAccountPda,
              mint,
              computationOffset: { first: resetComputationOffset },
              mpcCallbackDataOffset: { first: resetMpcCallbackDataOffset },
              priorityFees: { first: 0n },
              optionalData: { first: new Uint8Array(32) },
            };
            const resetInstruction = isSharedMode
              ? await getResetSharedEncryptedTokenAccountQueueV11InstructionAsync(resetBaseParams, {
                  programAddress: client.networkConfig.programId,
                })
              : await getResetNetworkEncryptedTokenAccountQueueV11InstructionAsync(resetBaseParams, {
                  programAddress: client.networkConfig.programId,
                });
            await executeTransaction(resetInstruction, resetAltEntry, undefined, {
              retrieveCallbackSignature: true,
              computationAccountAddress: resetArciumAccounts.computationAccount,
              computationOffset: BigInt(resetComputationOffset),
              clusterOffset: clusterOffset,
            });
          }
        }
      }

      if (hasX25519Key) {
        // Subcase 2.2: User HAS X25519 key registered
        if (tokenExists && isBalanceInitialised && isSharedMode) {
          // 2.2.1: Existing Shared balance
          instructionVariant = DepositInstructionVariant.ExistingSharedBalance;
        } else if (tokenExists && isBalanceInitialised && !isSharedMode) {
          // 2.2.2: Existing MXE balance
          instructionVariant = DepositInstructionVariant.ExistingMxeBalance;
        } else {
          // 2.2.3: Token doesn't exist OR balance not initialized
          instructionVariant = DepositInstructionVariant.NewSharedBalance;
        }
      } else {
        // Subcase 2.1: User has NO X25519 key registered
        if (tokenExists && isBalanceInitialised && isSharedMode) {
          // 2.1.1: Invalid state - can't have shared mode without X25519 key
          throw new EncryptedDepositError(
            "validation",
            "Invalid state: Token account is in Shared mode but user has no X25519 key registered",
          );
        } else if (tokenExists && isBalanceInitialised && !isSharedMode) {
          // 2.1.2: Existing MXE balance
          instructionVariant = DepositInstructionVariant.ExistingMxeBalance;
        } else {
          // 2.1.3: Token doesn't exist OR balance not initialized
          instructionVariant = DepositInstructionVariant.NewMxeBalance;
        }
      }
    } else {
      instructionVariant = DepositInstructionVariant.NewMxeBalance;
    }

    // ================================================================
    // Step 7: Generate computation offset and get Arcium accounts
    // ================================================================

    const computationOffset = generateRandomU64();

    // Map instruction variant to comp def instruction name (snake_case)
    const compDefInstructionName = {
      [DepositInstructionVariant.NewMxeBalance]: "deposit_from_public_balance_into_new_network_balance_v11",
      [DepositInstructionVariant.ExistingMxeBalance]:
        "deposit_from_public_balance_into_existing_network_balance_v11",
      [DepositInstructionVariant.NewSharedBalance]:
        "deposit_from_public_balance_into_new_shared_balance_v11",
      [DepositInstructionVariant.ExistingSharedBalance]:
        "deposit_from_public_balance_into_existing_shared_balance_v11",
    }[instructionVariant];

    // Look up the ALT entry for this instruction variant
    const altEntry = lookupAltEntry(client.networkConfig.addressLookupTables, clusterOffset, compDefInstructionName);

    // Get Arcium account addresses for the computation
    const arciumAccounts = await findArciumInfrastructurePdas(
      client.networkConfig.programId,
      client.networkConfig.arciumProgramAddress,
      clusterOffset,
      BigInt(computationOffset),
      compDefInstructionName,
    );

    // Generate random MPC callback data offset
    const mpcCallbackDataOffset = generateRandomU128();

    // Protocol fee provider for deposit category
    const protocolFeeProvider = getHardcodedDepositProtocolFeeProvider();
    const protocolFeeConfig = await protocolFeeProvider(depositAmount);

    // Common instruction parameters
    const noopSigner = createNoopSigner(signer.address);
    const commonParams = {
      depositorAddress: noopSigner,
      feePayer: noopSigner,
      receiverAddress: destinationAddress,
      mint,
      tokenProgram: mintOwner,
      // Arcium accounts
      mxeAccount: arciumAccounts.mxeAccount,
      mempoolAccount: arciumAccounts.mempoolAccount,
      executingPool: arciumAccounts.executingPoolAccount,
      computationAccount: arciumAccounts.computationAccount,
      compDefAccount: arciumAccounts.compDefAccount,
      clusterAccount: arciumAccounts.clusterAccount,
      // Instruction data
      computationOffset: { first: computationOffset },
      transferAmount: { first: transferAmount },
      depositAmount: { first: depositAmount },
      feeVaultOffset: { first: 0n },
      mpcCallbackDataOffset: { first: mpcCallbackDataOffset },
      optionalData: { first: optionalData },
      // Fee slab data and merkle proof
      ...feeSlabResultToInstructionFields(protocolFeeConfig),
    };

    // ================================================================
    // Step 8: Build instruction based on variant
    // ================================================================

    let instruction: Instruction;

    try {
      switch (instructionVariant) {
        case DepositInstructionVariant.NewMxeBalance: {
          instruction = await getDepositFromPublicBalanceIntoNewNetworkBalanceV11InstructionAsync(
            {
              ...commonParams,
              receiverTokenAccount: encryptedTokenAccountPda,
              receiverUserAccount: encryptedUserAccountPda,
              randomGenerationSeed: {
                first: crypto.getRandomValues(new Uint8Array(32)),
              },
              priorityFees: { first: microLamportsPerAcu },
            },
            { programAddress: client.networkConfig.programId },
          );
          break;
        }

        case DepositInstructionVariant.ExistingMxeBalance: {
          instruction = await getDepositFromPublicBalanceIntoExistingNetworkBalanceV11InstructionAsync(
            {
              ...commonParams,
              receiverTokenAccount: encryptedTokenAccountPda,
              priorityFees: { first: microLamportsPerAcu },
            },
            { programAddress: client.networkConfig.programId },
          );
          break;
        }

        case DepositInstructionVariant.NewSharedBalance: {
          instruction = await getDepositFromPublicBalanceIntoNewSharedBalanceV11InstructionAsync(
            {
              ...commonParams,
              receiverTokenAccount: encryptedTokenAccountPda,
              receiverUserAccount: encryptedUserAccountPda,
              priorityFees: { first: microLamportsPerAcu },
            },
            { programAddress: client.networkConfig.programId },
          );
          break;
        }

        case DepositInstructionVariant.ExistingSharedBalance: {
          instruction = await getDepositFromPublicBalanceIntoExistingSharedBalanceV11InstructionAsync(
            {
              ...commonParams,
              receiverTokenAccount: encryptedTokenAccountPda,
              priorityFees: { first: microLamportsPerAcu },
            },
            { programAddress: client.networkConfig.programId },
          );
          break;
        }

        default: {
          throw new EncryptedDepositError(
            "instruction-build",
            `Unknown instruction variant: ${String(instructionVariant)}`,
          );
        }
      }
    } catch (error) {
      if (error instanceof EncryptedDepositError) {
        throw error;
      }
      throw new EncryptedDepositError(
        "instruction-build",
        `Failed to build instruction: ${error instanceof Error ? error.message : String(error)}`,
        error instanceof Error ? error : undefined,
      );
    }

    // ================================================================
    // Step 9: Execute transaction
    // ================================================================

    const resolvedAwaitConfig =
      factoryAwaitComputationFinalization === false
        ? false
        : (factoryAwaitComputationFinalization ?? {});
    const callbackOptions: AwaitCallbackOptions | undefined =
      resolvedAwaitConfig === false
        ? undefined
        : {
            ...resolvedAwaitConfig,
            retrieveCallbackSignature: true,
            computationAccountAddress: arciumAccounts.computationAccount,
            computationOffset: BigInt(computationOffset),
            clusterOffset: clusterOffset,
          };

    return executeTransaction(
      instruction,
      altEntry,
      undefined,
      callbackOptions,
    );
  };
}
