/**
 * Creates the Fiat-Shamir challenge generator function using Keccak-256 with rejection sampling.
 *
 * @returns A fresh {@link FiatShamirChallengeGeneratorFunction} closure.
 *
 * @remarks
 * ## Algorithm
 *
 * This algorithm exactly mirrors the Rust on-chain implementation so that
 * off-chain TypeScript challenge generation produces the same values as the
 * Solana program's challenge derivation:
 *
 * 1. Compute `h = Keccak256(input)` — produces a 256-bit hash.
 * 2. Clear bit 255 of `h` (i.e. `h[31] &= 0x7F` in little-endian layout)
 *    to obtain a 255-bit value. This step guarantees the result is at most
 *    2^255 - 1, so the only values that are still ≥ p are those in the
 *    "gap" interval [p, 2^255 - 1] = [2^255 - 19, 2^255 - 1], which has
 *    size 19.
 * 3. Interpret the 32-byte array as a little-endian 256-bit unsigned integer.
 * 4. If the value is < p (the Curve25519 field prime), return it as a valid
 *    {@link Curve25519FieldElement}.
 * 5. Otherwise, re-hash the 32-byte array (`currentInput = h`) and repeat
 *    from step 1 — **hash chaining**, not counter appending.
 * 6. Abort after {@link MAX_REJECTION_ATTEMPTS} consecutive failures (this
 *    should never occur in practice).
 *
 * ## Security Properties
 *
 * Rejection sampling ensures that the output distribution is statistically
 * indistinguishable from uniform over GF(p). The bias from simply reducing
 * modulo p would be 19/2^255, which is negligible but non-zero; rejection
 * sampling eliminates even that residual bias.
 *
 * @internal
 *
 * @example
 * ```typescript
 * // Internal usage — prefer getFiatShamirChallengeGeneratorFunction()
 * const gen = createChallengeGeneratorFunction();
 * const transcript = new Uint8Array(64); // filled with public inputs
 * const challenge = gen(transcript);
 * ```
 */
function createChallengeGeneratorFunction(): FiatShamirChallengeGeneratorFunction {
  return (input: Uint8Array): Curve25519FieldElement => {
    let currentInput: Uint8Array = input;

    for (let attempt = 0; attempt < MAX_REJECTION_ATTEMPTS; attempt++) {
      const hash = keccak_256(currentInput);

      // Create mutable copy and clear bit 255 to constrain to 255 bits
      // In little-endian, bit 255 is bit 7 of byte[31]
      // Keccak-256 always produces 32 bytes, so index 31 is safe
      const hashBytes = new Uint8Array(hash);
      hashBytes[31] = hashBytes[31] & 0x7f;

      // Interpret as little-endian 256-bit integer
      let value = 0n;
      for (let index = 0; index < CURVE25519_BYTE_LENGTH; index++) {
        value |= BigInt(hashBytes[index]) << BigInt(index * 8);
      }

      // Check if the value is within the field (< 2^255 - 19)
      if (value < CURVE25519_FIELD_PRIME) {
        assertCurve25519FieldElement(value, "fiatShamirChallenge");
        return value;
      }

      // Rejection: re-hash the hash output (hash chaining)
      currentInput = hashBytes;
    }

    throw new Error(
      `Fiat-Shamir challenge generation failed after ${String(MAX_REJECTION_ATTEMPTS)} attempts. ` +
        "This is extremely unlikely and may indicate a bug or corrupted input.",
    );
  };
}

/**
 * Creates the challenge powers computation function using a given modular multiplication implementation.
 *
 * @param moduleMul - The modular multiplication function to use for field arithmetic.
 * @returns A {@link ChallengePowersFunction} that iteratively multiplies to produce powers.
 *
 * @remarks
 * ## Algorithm
 *
 * Powers are computed iteratively rather than via repeated squaring or
 * `BigInt ** n`, because in a ZK context we need exactly `[c^0, c^1, ..., c^n]`
 * (all intermediate values), and iterative multiplication produces them in a
 * single pass with exactly `n-1` multiplications:
 *
 * ```
 * powers[0] = 1
 * powers[1] = challenge
 * powers[i] = powers[i-1] * challenge  (mod p)
 * ```
 *
 * ## Validation
 *
 * - `maxPower` must be a non-negative integer; a negative value throws immediately.
 * - Each intermediate result is asserted to be a valid {@link Curve25519FieldElement}
 *   via {@link assertCurve25519FieldElement}, so overflow or underflow bugs are
 *   caught at the source.
 *
 * @internal
 *
 * @example
 * ```typescript
 * // Internal usage
 * const modMul = getCurve25519ModuleMulFunction();
 * const powFn = createChallengePowersFunction(modMul);
 * const powers = powFn(challenge, 3);
 * // powers[0] === 1n, powers[1] === challenge, powers[2] === challenge^2, powers[3] === challenge^3
 * ```
 */
function createChallengePowersFunction(
  moduleMul: Curve25519ModuleMulFunction,
): ChallengePowersFunction {
  return (challenge: Curve25519FieldElement, maxPower: number): Curve25519FieldElement[] => {
    if (maxPower < 0) {
      throw new Error(
        `maxPower must be non-negative, got ${String(maxPower)}. ` +
          "Provide a non-negative integer for the maximum power.",
      );
    }

    const powers: Curve25519FieldElement[] = Array.from<Curve25519FieldElement>({
      length: maxPower + 1,
    });

    // powers[0] = 1 (challenge^0)
    assertCurve25519FieldElement(1n, "powers[0]");
    powers[0] = 1n as Curve25519FieldElement;

    if (maxPower === 0) {
      return powers;
    }

    // powers[1] = challenge
    powers[1] = challenge;

    // Compute remaining powers iteratively
    let current: bigint = challenge;
    for (let index = 2; index <= maxPower; index++) {
      current = moduleMul(current, challenge);
      assertCurve25519FieldElement(current, `powers[${String(index)}]`);
      powers[index] = current;
    }

    return powers;
  };
}

/**
 * Creates a polynomial evaluator using Horner's method with the given field arithmetic.
 *
 * @param moduleAdd - The modular addition function to use for field arithmetic.
 * @param moduleMul - The modular multiplication function to use for field arithmetic.
 * @returns A {@link PolynomialEvaluatorFunction} that evaluates univariate polynomials over GF(p).
 *
 * @remarks
 * ## Horner's Method
 *
 * For a polynomial P(x) = c[0] + c[1]·x + c[2]·x² + ... + c[n]·x^n,
 * Horner's method rewrites it as a nested multiplication:
 * ```
 * P(x) = c[0] + x·(c[1] + x·(c[2] + ... + x·c[n]))
 * ```
 * This requires exactly n multiplications and n additions (versus 2n-1
 * multiplications for the naïve evaluation) and is numerically stable.
 *
 * ## Iteration Direction
 *
 * The implementation iterates from `coefficients[length-1]` (highest degree)
 * down to `coefficients[0]` (constant term), accumulating the result inward.
 *
 * ## Edge Cases
 *
 * - An empty `coefficients` array returns `0n` (the zero polynomial).
 * - A single-element array returns `coefficients[0]` (a constant polynomial,
 *   independent of `point`).
 *
 * @internal
 *
 * @example
 * ```typescript
 * // Internal usage — evaluates P(x) = 1 + 2x + 3x^2 at x=2
 * const modAdd = getCurve25519ModuleAddFunction();
 * const modMul = getCurve25519ModuleMulFunction();
 * const evalFn = createPolynomialEvaluatorFunction(modAdd, modMul);
 *
 * const coeffs = [1n, 2n, 3n] as Curve25519FieldElement[];
 * const point  = 2n as Curve25519FieldElement;
 * const result = evalFn(coeffs, point);
 * // result === 17n  (1 + 4 + 12)
 * ```
 */
function createPolynomialEvaluatorFunction(
  moduleAdd: Curve25519ModuleAddFunction,
  moduleMul: Curve25519ModuleMulFunction,
): PolynomialEvaluatorFunction {
  return (
    coefficients: Curve25519FieldElement[],
    point: Curve25519FieldElement,
  ): Curve25519FieldElement => {
    if (coefficients.length === 0) {
      assertCurve25519FieldElement(0n, "emptyPolynomialResult");
      return 0n as Curve25519FieldElement;
    }

    // Horner's method: start from highest degree coefficient
    const lastCoefficient = coefficients.at(-1);
    if (lastCoefficient === undefined) {
      throw new Error("Unexpected empty coefficients array after length check");
    }

    let result: bigint = lastCoefficient;

    for (let index = coefficients.length - 2; index >= 0; index--) {
      // result = result * point + coefficients[i]
      result = moduleMul(result, point);

      const sum = moduleAdd(result, coefficients[index]);
      assertCurve25519FieldElement(sum, "polynomialIntermediateSum");
      result = sum;
    }

    return result as Curve25519FieldElement;
  };
}

/**
 * Creates the modular exponentiation function for the Curve25519 field.
 *
 * @returns A {@link ModuloPowCurve25519Function} that wraps {@link curve25519ModuloPow}
 *          with validation of its output.
 *
 * @remarks
 * The underlying `curve25519ModuloPow` uses the standard binary
 * square-and-multiply algorithm, which runs in O(log exp) field multiplications.
 * The zero-exponent special case is handled explicitly (returns `1n`) to
 * avoid an unnecessary call into the underlying function.
 *
 * The output is validated via {@link assertCurve25519FieldElement} so any
 * arithmetic overflow in the underlying implementation would be caught
 * immediately rather than silently propagating wrong values.
 *
 * @internal
 *
 * @example
 * ```typescript
 * // Internal usage
 * const powFn = createModulePowFunction();
 * const base = 2n as Curve25519FieldElement;
 * const result = powFn(base, 10n);
 * // result === 1024n
 * ```
 */
function createModulePowFunction(): ModuloPowCurve25519Function {
  return (base: Curve25519FieldElement, exp: bigint): Curve25519FieldElement => {
    if (exp === 0n) {
      assertCurve25519FieldElement(1n, "modPowZeroExp");
      return 1n as Curve25519FieldElement;
    }

    const result = curve25519ModulePow(base, exp);
    assertCurve25519FieldElement(result, "modPowResult");
    return result;
  };
}

