/* =============================================================================
 * X25519 KEYPAIR ASSERTION
 * ============================================================================= */

/**
 * Asserts that a value is a valid X25519Keypair.
 *
 * Validates that the value is a non-null object with valid `privateKey` and
 * `publicKey` fields, each of which must pass their respective assertions.
 *
 * @param value - The object to assert as an X25519Keypair
 * @throws {CryptographyAssertionError} If the value is not a non-null object
 * @throws {CryptographyAssertionError} If `privateKey` or `publicKey` are missing
 * @throws {CryptographyAssertionError} If either key fails its byte-level assertion
 *
 * @example
 * ```typescript
 * const keypair = { privateKey: privKey, publicKey: pubKey };
 * assertX25519Keypair(keypair);
 * // keypair is now typed as X25519Keypair
 * ```
 *
 * @see {@link X25519Keypair}
 * @see {@link assertX25519PrivateKey}
 * @see {@link assertX25519PublicKey}
 * @public
 */
export function assertX25519Keypair(value: {
  privateKey: Uint8Array;
  publicKey: Uint8Array;
}): asserts value is X25519Keypair {
   
  if (typeof value !== "object" || value === null) {
    throw new CryptographyAssertionError(`Expected object, got ${typeof value}`, {
      value,
      expectedType: "X25519Keypair",
    });
  }

  if (!("privateKey" in value) || !("publicKey" in value)) {
    throw new CryptographyAssertionError(
      `Expected object with privateKey and publicKey properties`,
      {
        value,
        expectedType: "X25519Keypair",
        constraint: "must have privateKey and publicKey",
      },
    );
  }

  // Validate private key
  assertX25519PrivateKey(value.privateKey);

  // Validate public key
  assertX25519PublicKey(value.publicKey);
}

/**
 * Asserts that a value is a valid Ed25519Keypair.
 *
 * Validates that the value is a non-null object with `seed` (exactly 32 bytes)
 * and `publicKey` (exactly 32 bytes) properties.
 *
 * @param value - The object to assert as an Ed25519Keypair (must have seed and publicKey properties)
 * @throws {CryptographyAssertionError} If the value is not a non-null object
 * @throws {CryptographyAssertionError} If `seed` or `publicKey` are missing
 * @throws {CryptographyAssertionError} If `seed` or `publicKey` are not Uint8Array(32)
 *
 * @example
 * ```typescript
 * const keypair = { seed, publicKey };
 * assertEd25519Keypair(keypair);
 * // keypair is now typed as Ed25519Keypair
 * ```
 *
 * @see {@link Ed25519Keypair}
 * @public
 */
export function assertEd25519Keypair(value: {
  seed: Uint8Array;
  publicKey: Uint8Array;
}): asserts value is Ed25519Keypair {
   
  if (typeof value !== "object" || value === null) {
    throw new CryptographyAssertionError(`Expected object, got ${typeof value}`, {
      value,
      expectedType: "Ed25519Keypair",
    });
  }

  if (!("seed" in value) || !("publicKey" in value)) {
    throw new CryptographyAssertionError(`Expected object with seed and publicKey properties`, {
      value,
      expectedType: "Ed25519Keypair",
      constraint: "must have seed and publicKey",
    });
  }

  // Validate seed (32 bytes)
  if (!(value.seed instanceof Uint8Array)) {
    throw new CryptographyAssertionError(`seed must be Uint8Array`, {
      value: value.seed,
      expectedType: "Ed25519Keypair",
      constraint: "seed: Uint8Array(32)",
    });
  }
  if (value.seed.length !== 32) {
    throw new CryptographyAssertionError(
      `seed must be exactly 32 bytes, got ${String(value.seed.length)}`,
      {
        value: value.seed,
        expectedType: "Ed25519Keypair",
        constraint: "seed.length === 32",
      },
    );
  }

  // Validate public key (32 bytes)
  if (!(value.publicKey instanceof Uint8Array)) {
    throw new CryptographyAssertionError(`publicKey must be Uint8Array`, {
      value: value.publicKey,
      expectedType: "Ed25519Keypair",
      constraint: "publicKey: Uint8Array(32)",
    });
  }
  if (value.publicKey.length !== 32) {
    throw new CryptographyAssertionError(
      `publicKey must be exactly 32 bytes, got ${String(value.publicKey.length)}`,
      {
        value: value.publicKey,
        expectedType: "Ed25519Keypair",
        constraint: "publicKey.length === 32",
      },
    );
  }
}

/**
 * Asserts that a value is a valid Curve25519KeypairResult.
 *
 * Validates that the value is a non-null object with valid `ed25519Keypair`
 * and `x25519Keypair` fields, each of which must pass their respective assertions.
 *
 * @param value - The object to assert as a Curve25519KeypairResult
 * @throws {CryptographyAssertionError} If the value is not a non-null object
 * @throws {CryptographyAssertionError} If either nested keypair is missing or invalid
 *
 * @example
 * ```typescript
 * const result = { ed25519Keypair, x25519Keypair };
 * assertCurve25519KeypairResult(result);
 * // result is now typed as Curve25519KeypairResult
 * ```
 *
 * @see {@link Curve25519KeypairResult}
 * @see {@link assertEd25519Keypair}
 * @see {@link assertX25519Keypair}
 * @public
 */
export function assertCurve25519KeypairResult(value: {
  ed25519Keypair: { seed: Uint8Array; publicKey: Uint8Array };
  x25519Keypair: { privateKey: Uint8Array; publicKey: Uint8Array };
}): asserts value is Curve25519KeypairResult {
   
  if (typeof value !== "object" || value === null) {
    throw new CryptographyAssertionError(`Expected object, got ${typeof value}`, {
      value,
      expectedType: "Curve25519KeypairResult",
    });
  }

  if (!("ed25519Keypair" in value) || !("x25519Keypair" in value)) {
    throw new CryptographyAssertionError(
      `Expected object with ed25519Keypair and x25519Keypair properties`,
      {
        value,
        expectedType: "Curve25519KeypairResult",
        constraint: "must have ed25519Keypair and x25519Keypair",
      },
    );
  }

  // Validate ed25519 keypair
  assertEd25519Keypair(value.ed25519Keypair);

  // Validate x25519 keypair
  assertX25519Keypair(value.x25519Keypair);
}
