import type { UserRegistrationFunction } from "../../interfaces";
import type { TransactionSignature } from "../../../types";

/**
 * Creates a function that rotates the master viewing key (MVK) X25519 public key
 * and re-registers the user commitment for anonymous usage.
 *
 * @remarks
 * This is a convenience wrapper around a pre-built {@link UserRegistrationFunction}
 * that runs only the anonymous usage registration step with `confidential: false`.
 * Use this when the client has been constructed with a new offset affecting the
 * MVK-encrypting X25519 keypair and you need to push the updated keys and
 * re-register the user commitment on-chain.
 *
 * The returned function skips the transaction if both the current derived MVK
 * X25519 key and the locally recomputed user commitment already match what is
 * stored on-chain. It re-registers if either has changed.
 *
 * @param register - A pre-built registration function created via
 *   `getUserRegistrationFunction({ client }, deps)`. Must have been built with
 *   a `zkProver` in deps since anonymous registration requires ZK proof generation.
 * @returns A zero-argument function that executes the MVK key rotation and returns
 *   an array of confirmed transaction signatures (one entry on rotation, empty
 *   array if the key and commitment were already up to date).
 *
 * @example
 * ```typescript
 * import {
 *   getUserRegistrationFunction,
 *   getRotateMvkX25519KeyFunction,
 * } from "@umbra-privacy/sdk";
 *
 * const register = getUserRegistrationFunction({ client }, { zkProver });
 * const rotateKey = getRotateMvkX25519KeyFunction(register);
 * const signatures = await rotateKey();
 * console.log("MVK rotation signatures:", signatures);
 * ```
 *
 * @public
 */
export function getMasterViewingKeyRotatorFunction(
  register: UserRegistrationFunction,
): () => Promise<TransactionSignature[]> {
  return () => register({ confidential: false, anonymous: true });
}
